// src/pos/Cashier.js
// ============================================================
// Cashier Management — React + Firestore (hybrid)
// ------------------------------------------------------------
// Reads:  Firestore  (listCollection("Cashier"))
// Writes: transitional Node server (bcrypt + Admin SDK) via
//         the Firebase-token-aware axios instance in ../api.js
//
// Preserves:
//   • Full permission gating (View / Add / Edit / Delete)
//   • Password required on create, optional on update
//   • Type / Encode / LocationID fields
//   • Read-only badge, permission helper text
//   • Soft-delete on the Firestore side is handled server-side
//     (CashierPermissions rows are cleaned up too)
// ============================================================
import React, { useContext, useEffect, useState } from "react";
import { AuthContext } from "./SERVER/AuthContext.js";
import { usePermissions } from "../hooks/usePermissions.jsx";
import { listCollection } from "../lib/firestore";
import api from "../api";

const emptyForm = {
  Code: "",
  LocationID: "",
  Name: "",
  LogName: "",
  Password: "",
  Encode: "",
  Type: 0,
};

export default function Cashier() {
  const { user } = useContext(AuthContext);
  const { can, loading: permissionsLoading } = usePermissions();

  // ---- PERMISSIONS ----
  const canViewCashier   = can("Cashier", "View");
  const canAddCashier    = can("Cashier", "Add");
  const canEditCashier   = can("Cashier", "Edit");
  const canDeleteCashier = can("Cashier", "Delete");

  // ---- STATE ----
  const [form, setForm]             = useState(emptyForm);
  const [cashiers, setCashiers]     = useState([]);
  const [editingId, setEditingId]   = useState(null); // Firestore doc id
  const [loading, setLoading]       = useState(false);
  const [loadingList, setLoadingList] = useState(false);
  const [message, setMessage]       = useState("");
  const [error, setError]           = useState("");

  // ============================================================
  // LOAD CASHIERS (Firestore)
  // ============================================================
  const loadCashiers = async () => {
    try {
      setLoadingList(true);
      setError("");

      const rows = await listCollection("Cashier");
      // Newest first, matching the SQL ORDER BY CashierID DESC
      rows.sort((a, b) => Number(b.CashierID || 0) - Number(a.CashierID || 0));
      setCashiers(rows);
    } catch (err) {
      console.error("LOAD CASHIERS ERROR:", err);
      setError(err?.message || "Unable to load cashiers.");
      setCashiers([]);
    } finally {
      setLoadingList(false);
    }
  };

  useEffect(() => {
    if (permissionsLoading) return;
    if (!canViewCashier) return;
    loadCashiers();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [permissionsLoading, canViewCashier]);

  // ============================================================
  // INPUT
  // ============================================================
  const handleChange = (e) => {
    const { name, value } = e.target;
    setForm((p) => ({ ...p, [name]: value }));
    setMessage("");
    setError("");
  };

  const clearForm = () => {
    setForm(emptyForm);
    setEditingId(null);
    setMessage("");
    setError("");
  };

  // ============================================================
  // NEW
  // ============================================================
  const handleNew = () => {
    if (!canAddCashier) {
      setError("You do not have permission to create cashiers.");
      return;
    }
    clearForm();
  };

  // ============================================================
  // VALIDATION
  // ============================================================
  const validate = () => {
    if (!form.Code.trim())       { setError("Cashier Code is required.");          return false; }
    if (!form.Name.trim())       { setError("Cashier Name is required.");          return false; }
    if (!form.LogName.trim())    { setError("Login Name is required.");            return false; }
    if (!form.LocationID)        { setError("Location ID is required.");           return false; }
    if (!editingId && !form.Password.trim()) {
      setError("Password is required when creating a cashier.");
      return false;
    }
    return true;
  };

  // ============================================================
  // SAVE / UPDATE  (through the transitional Node server)
  // ============================================================
  const handleSubmit = async (e) => {
    e.preventDefault();
    setMessage("");
    setError("");

    // Permission gates
    if (editingId && !canEditCashier) { setError("You do not have permission to edit cashiers.");   return; }
    if (!editingId && !canAddCashier) { setError("You do not have permission to create cashiers."); return; }

    if (!validate()) return;

    try {
      setLoading(true);

      if (editingId) {
        // ---- UPDATE ----
        // Password is only sent when the user actually typed a new one,
        // so the server can skip re-hashing on cosmetic edits.
        const payload = {
          Code:       form.Code.trim(),
          LocationID: Number(form.LocationID),
          Name:       form.Name.trim(),
          LogName:    form.LogName.trim(),
          Type:       Number(form.Type),
          Encode:     form.Encode.trim(),
        };
        if (form.Password.trim()) payload.Password = form.Password;

        await api.put(`/cashiers/${editingId}`, payload);
        setMessage("Cashier updated successfully.");
      } else {
        // ---- CREATE ----
        // Server bcrypts the password, writes the Cashier doc via
        // Admin SDK, and seeds the default CashierPermissions rows.
        const payload = {
          Code:       form.Code.trim(),
          LocationID: Number(form.LocationID),
          Name:       form.Name.trim(),
          LogName:    form.LogName.trim(),
          Password:   form.Password,
          Encode:     form.Encode.trim(),
          Type:       Number(form.Type),
        };

        await api.post("/cashiers", payload);
        setMessage("Cashier created successfully.");
      }

      clearForm();
      await loadCashiers();
    } catch (err) {
      console.error("SAVE CASHIER ERROR:", err);
      setError(
        err?.response?.data?.message ||
        err?.message ||
        "Unable to save cashier."
      );
    } finally {
      setLoading(false);
    }
  };

  // ============================================================
  // EDIT
  // ============================================================
  const handleEdit = (cashier) => {
    if (!canEditCashier) {
      setError("You do not have permission to edit cashiers.");
      return;
    }

    setForm({
      Code:       cashier.Code       ?? "",
      LocationID: cashier.LocationID ?? "",
      Name:       cashier.Name       ?? "",
      LogName:    cashier.LogName    ?? "",
      Password:   "",                 // never pre-fill a password
      Encode:     cashier.Encode     ?? "",
      Type:       cashier.Type       ?? 0,
    });
    setEditingId(cashier.id);
    setMessage(`Editing ${cashier.LogName}`);
    setError("");
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  // ============================================================
  // DELETE  (hard delete on server + cascades CashierPermissions)
  // ============================================================
  const handleDelete = async (cashier) => {
    if (!canDeleteCashier) {
      setError("You do not have permission to delete cashiers.");
      return;
    }
    if (!cashier?.id) {
      setError("Invalid cashier.");
      return;
    }
    if (!window.confirm(`Are you sure you want to delete cashier "${cashier.Name}"?`)) return;

    try {
      setLoading(true);
      setMessage("");
      setError("");

      await api.delete(`/cashiers/${cashier.id}`);
      setMessage("Cashier deleted successfully.");

      if (editingId === cashier.id) clearForm();
      await loadCashiers();
    } catch (err) {
      console.error("DELETE CASHIER ERROR:", err);
      setError(err?.response?.data?.message || "Unable to delete cashier.");
    } finally {
      setLoading(false);
    }
  };

  // ============================================================
  // COMPUTED
  // ============================================================
  const isEditing    = Boolean(editingId);
  const saveAllowed  = (isEditing && canEditCashier) || (!isEditing && canAddCashier);
  const readOnlyEdit = isEditing && !canEditCashier;

  // ============================================================
  // ACCESS GATE
  // ============================================================
  if (permissionsLoading) {
    return (
      <div className="min-h-screen bg-gray-100 p-6 flex items-center justify-center text-gray-500">
        Checking permissions…
      </div>
    );
  }

  if (!canViewCashier) {
    return (
      <div className="min-h-screen bg-gray-100 p-6">
        <div className="mx-auto max-w-xl mt-20 rounded-xl border border-red-200 bg-red-50 p-8 text-center">
          <h2 className="text-lg font-bold text-red-700">Access Denied</h2>
          <p className="text-sm text-red-600 mt-2">
            You do not have permission to view Cashiers.
          </p>
          <p className="text-xs text-red-400 mt-3">
            Module: <code>Cashier</code>
          </p>
        </div>
      </div>
    );
  }

  // ============================================================
  // RENDER
  // ============================================================
  return (
    <div className="p-6">
      {/* PAGE TITLE */}
      <div className="mb-6 flex items-start justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-800">Cashier Management</h1>
          <p className="text-gray-500 mt-1">Create and manage system cashiers.</p>
        </div>

        {canAddCashier && (
          <button
            type="button"
            onClick={handleNew}
            className="bg-blue-600 hover:bg-blue-700 text-white px-5 py-2.5 rounded-lg font-medium"
          >
            + New Cashier
          </button>
        )}
      </div>

      {/* MESSAGES */}
      {message && (
        <div className="mb-4 rounded-lg border border-green-200 bg-green-50 px-4 py-3 text-sm font-medium text-green-700">
          ✓ {message}
        </div>
      )}
      {error && (
        <div className="mb-4 rounded-lg border border-red-200 bg-red-50 px-4 py-3 text-sm font-medium text-red-700">
          ⚠ {error}
        </div>
      )}

      {/* FORM */}
      <div className="bg-white rounded-xl shadow p-6 mb-8">
        <div className="flex items-center justify-between mb-5">
          <h2 className="text-lg font-semibold text-gray-800">
            {isEditing ? "Edit Cashier" : "Create Cashier"}
          </h2>
          {readOnlyEdit && (
            <span className="rounded-full bg-slate-200 px-3 py-1 text-xs font-semibold text-slate-600">
              READ ONLY
            </span>
          )}
        </div>

        <form onSubmit={handleSubmit} className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {/* Cashier Code */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Cashier Code
            </label>
            <input
              type="text"
              name="Code"
              value={form.Code}
              onChange={handleChange}
              maxLength={50}
              placeholder="Enter cashier code"
              className="w-full border rounded-lg p-3 focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>

          {/* Cashier Name */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Cashier Name
            </label>
            <input
              type="text"
              name="Name"
              value={form.Name}
              onChange={handleChange}
              maxLength={250}
              placeholder="Enter cashier name"
              className="w-full border rounded-lg p-3 focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>

          {/* Login Name */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Login Name
            </label>
            <input
              type="text"
              name="LogName"
              value={form.LogName}
              onChange={handleChange}
              maxLength={250}
              placeholder="Enter login name"
              className="w-full border rounded-lg p-3 focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>

          {/* Password */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Password
              {isEditing && (
                <span className="text-gray-400 ml-2">
                  (leave blank to keep current password)
                </span>
              )}
            </label>
            <input
              type="password"
              name="Password"
              value={form.Password}
              onChange={handleChange}
              maxLength={250}
              placeholder={isEditing ? "New password" : "Enter password"}
              autoComplete="new-password"
              className="w-full border rounded-lg p-3 focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>

          {/* Location ID */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Location ID
            </label>
            <input
              type="number"
              name="LocationID"
              value={form.LocationID}
              onChange={handleChange}
              min="1"
              placeholder="Enter location ID"
              className="w-full border rounded-lg p-3 focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>

          {/* Type */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Cashier Type
            </label>
            <input
              type="number"
              name="Type"
              value={form.Type}
              onChange={handleChange}
              placeholder="Cashier type"
              className="w-full border rounded-lg p-3 focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>

          {/* Encode */}
          <div className="md:col-span-2">
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Encode
            </label>
            <input
              type="text"
              name="Encode"
              value={form.Encode}
              onChange={handleChange}
              maxLength={250}
              placeholder="Encode value (optional)"
              className="w-full border rounded-lg p-3 focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>

          {/* BUTTONS */}
          <div className="md:col-span-2 flex flex-wrap gap-3 pt-2">
            {saveAllowed && (
              <button
                type="submit"
                disabled={loading}
                className="bg-blue-600 hover:bg-blue-700 disabled:bg-blue-300 text-white px-6 py-3 rounded-lg font-medium"
              >
                {loading
                  ? "Saving…"
                  : isEditing
                  ? "Update Cashier"
                  : "Save Cashier"}
              </button>
            )}

            <button
              type="button"
              onClick={clearForm}
              disabled={loading}
              className="bg-gray-500 hover:bg-gray-600 text-white px-6 py-3 rounded-lg font-medium"
            >
              Clear
            </button>

            {readOnlyEdit && (
              <div className="flex items-center rounded-lg border border-slate-200 bg-slate-50 px-4 py-3 text-xs font-semibold text-slate-500">
                You have read-only access — editing is disabled.
              </div>
            )}

            {!isEditing && !canAddCashier && (
              <div className="flex items-center rounded-lg border border-slate-200 bg-slate-50 px-4 py-3 text-xs font-semibold text-slate-500">
                You do not have permission to create new cashiers.
              </div>
            )}
          </div>
        </form>
      </div>

      {/* CASHIER TABLE */}
      <div className="bg-white rounded-xl shadow overflow-hidden">
        <div className="p-5 border-b flex items-center justify-between">
          <h2 className="text-lg font-semibold">
            Cashiers
            <span className="ml-2 text-sm font-normal text-gray-500">
              ({cashiers.length})
            </span>
          </h2>
          <button
            type="button"
            onClick={loadCashiers}
            disabled={loadingList}
            className="text-sm text-blue-600 hover:text-blue-700 font-medium disabled:opacity-50"
          >
            {loadingList ? "Loading…" : "Refresh"}
          </button>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full">
            <thead className="bg-gray-100">
              <tr>
                <th className="p-3 text-left">ID</th>
                <th className="p-3 text-left">Code</th>
                <th className="p-3 text-left">Name</th>
                <th className="p-3 text-left">Login Name</th>
                <th className="p-3 text-left">Location</th>
                <th className="p-3 text-left">Type</th>
                <th className="p-3 text-center">Action</th>
              </tr>
            </thead>

            <tbody>
              {loadingList ? (
                <tr>
                  <td colSpan="7" className="p-8 text-center text-gray-500">
                    Loading cashiers…
                  </td>
                </tr>
              ) : cashiers.length === 0 ? (
                <tr>
                  <td colSpan="7" className="p-8 text-center text-gray-500">
                    No cashiers found.
                  </td>
                </tr>
              ) : (
                cashiers.map((cashier) => (
                  <tr
                    key={cashier.id}
                    className="border-t hover:bg-gray-50"
                  >
                    <td className="p-3">{cashier.CashierID ?? cashier.id}</td>
                    <td className="p-3 font-medium">{cashier.Code}</td>
                    <td className="p-3">{cashier.Name}</td>
                    <td className="p-3">{cashier.LogName}</td>
                    <td className="p-3">{cashier.LocationID}</td>
                    <td className="p-3">{cashier.Type}</td>

                    <td className="p-3">
                      <div className="flex justify-center gap-2">
                        {canEditCashier && (
                          <button
                            type="button"
                            onClick={() => handleEdit(cashier)}
                            className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded"
                          >
                            Edit
                          </button>
                        )}
                        {canDeleteCashier && (
                          <button
                            type="button"
                            onClick={() => handleDelete(cashier)}
                            className="bg-red-600 hover:bg-red-700 text-white px-4 py-2 rounded"
                          >
                            Delete
                          </button>
                        )}
                        {!canEditCashier && !canDeleteCashier && (
                          <span className="text-xs text-slate-400">No actions</span>
                        )}
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}