// src/pos/SERVER/AuthContext.js
import React, {
  createContext,
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import {
  onAuthStateChanged,
  signInWithEmailAndPassword,
  signOut,
} from "firebase/auth";
import {
  doc,
  getDoc,
  getDocFromCache,
  collection,
  query,
  where,
  getDocs,
} from "firebase/firestore";
import { auth, db } from "../../firebase.js";

export const AuthContext = createContext(null);

const PROFILE_COLLECTIONS = ["cashier"];

const CASHIER_ID_KEYS = [
  "CashierID",
  "CashierId",
  "cashierID",
  "cashierId",
  "UserID",
  "userID",
  "UserId",
  "userId",
];

const EMAIL_FIELD_CANDIDATES = [
  "Email",
  "email",
  "UserEmail",
  "userEmail",
  "LogName",
  "UserName",
];

const UID_FIELD_CANDIDATES = [
  "AuthUID",
  "authUid",
  "FirebaseUID",
  "UID",
  "uid",
];

const PROFILE_TIMEOUT_MS = 7000;
const LEGACY_USER_KEY = "user";

const cacheKey = (uid) => `auth.profile.${uid}`;

/* ---------- helpers ---------- */

const normalizeCashierId = (value) => {
  if (value == null) return null;

  if (
    typeof value === "object" &&
    typeof value.id === "string" &&
    typeof value.path === "string"
  ) {
    return normalizeCashierId(value.id);
  }

  if (typeof value === "number") {
    return Number.isFinite(value) && value > 0 ? value : null;
  }

  const str = String(value).trim();
  if (!str) return null;

  const lower = str.toLowerCase();
  if (lower === "null" || lower === "undefined" || lower === "nan") {
    return null;
  }

  if (/^\d+$/.test(str)) {
    const n = Number(str);
    return n > 0 ? n : null;
  }

  return str;
};

const firstCashierId = (...sources) => {
  for (const source of sources) {
    if (source == null) continue;

    if (typeof source !== "object") {
      const id = normalizeCashierId(source);
      if (id != null) return id;
      continue;
    }

    for (const key of CASHIER_ID_KEYS) {
      if (Object.prototype.hasOwnProperty.call(source, key)) {
        const id = normalizeCashierId(source[key]);
        if (id != null) return id;
      }
    }
  }
  return null;
};

const parseObject = (raw) => {
  if (!raw) return null;
  try {
    const v = JSON.parse(raw);
    return v && typeof v === "object" && !Array.isArray(v) ? v : null;
  } catch {
    return null;
  }
};

const readLegacyUser = () => {
  try {
    return parseObject(localStorage.getItem(LEGACY_USER_KEY));
  } catch {
    return null;
  }
};

const readCache = (uid) => {
  try {
    return parseObject(localStorage.getItem(cacheKey(uid)));
  } catch {
    return null;
  }
};

const persistUser = (user) => {
  if (!user?.uid) return;
  try {
    const payload = {
      ...user,
      profileSyncedAt: new Date().toISOString(),
    };
    localStorage.setItem(cacheKey(user.uid), JSON.stringify(payload));
    if (user.CashierID != null || user.email) {
      localStorage.setItem(LEGACY_USER_KEY, JSON.stringify(payload));
    }
  } catch {
    // ignore
  }
};

const clearCache = (uid) => {
  try {
    localStorage.removeItem(cacheKey(uid));
  } catch {
    // ignore
  }
};

const clearLegacyUser = () => {
  try {
    localStorage.removeItem(LEGACY_USER_KEY);
  } catch {
    // ignore
  }
};

const withTimeout = (promise, ms, label) => {
  let timer;
  const timeout = new Promise((_, reject) => {
    timer = setTimeout(() => reject(new Error(`${label} timed out`)), ms);
  });
  promise.catch(() => {});
  return Promise.race([promise, timeout]).finally(() => clearTimeout(timer));
};

const legacyMatchesAuthUser = (legacy, fbUser) => {
  if (!legacy) return false;
  const legacyEmail = String(legacy.email ?? legacy.Email ?? "")
    .trim()
    .toLowerCase();
  const authEmail = String(fbUser?.email ?? "").trim().toLowerCase();
  if (legacyEmail && authEmail && legacyEmail !== authEmail) return false;
  return true;
};

function makeProfile(snapshot, collectionName, source) {
  const raw = snapshot.data() || {};
  const id = snapshot.id;
  const data = { ...raw, id };

  const isCashierCollection =
    collectionName === "cashier" || collectionName === "Cashier";

  if (isCashierCollection && firstCashierId(data) == null) {
    const docId = normalizeCashierId(id);
    if (docId != null) data.CashierID = docId;
  }

  return { collection: collectionName, source, id, data };
}

const buildUser = (fbUser, { legacy, cache, profileDoc } = {}) => {
  const safeLegacy = legacyMatchesAuthUser(legacy, fbUser) ? legacy : null;
  const profileData = profileDoc?.data || null;

  const merged = {
    ...(safeLegacy || {}),
    ...(cache || {}),
    ...(profileData || {}),
  };

  const cashierId =
    firstCashierId(profileData) ??
    firstCashierId(cache) ??
    firstCashierId(safeLegacy);

  return {
    ...merged,
    uid: fbUser.uid,
    email: fbUser.email || merged.email || merged.Email || "",
    CashierID: 1,
  };
};

/* ---------- Phase 2: cashier query fallback ---------- */

async function queryCashierProfile(fbUser) {
  const cashierCol = collection(db, "cashier");
  const email = String(fbUser.email || "").trim();
  const uid = fbUser.uid;

  if (email) {
    const variants = [
      ...new Set([email, email.toLowerCase(), email.toUpperCase()]),
    ];
    for (const field of EMAIL_FIELD_CANDIDATES) {
      for (const value of variants) {
        try {
          const snap = await getDocs(
            query(cashierCol, where(field, "==", value))
          );
          if (!snap.empty) {
            const doc0 = snap.docs[0];
            console.info(
              `[Auth] Profile from query: cashier.${field} == ${value} → ${doc0.id}`
            );
            return makeProfile(doc0, "cashier", "query");
          }
        } catch (err) {
          if (err?.code !== "failed-precondition") {
            console.warn(
              `[Auth] cashier query ${field} == ${value} failed:`,
              err?.code || err?.message || err
            );
          }
        }
      }
    }
  }

  if (uid) {
    for (const field of UID_FIELD_CANDIDATES) {
      try {
        const snap = await getDocs(
          query(cashierCol, where(field, "==", uid))
        );
        if (!snap.empty) {
          const doc0 = snap.docs[0];
          console.info(
            `[Auth] Profile from query: cashier.${field} == ${uid} → ${doc0.id}`
          );
          return makeProfile(doc0, "cashier", "query");
        }
      } catch (err) {
        if (err?.code !== "failed-precondition") {
          console.warn(
            `[Auth] cashier query ${field} == ${uid} failed:`,
            err?.code || err?.message || err
          );
        }
      }
    }
  }

  return null;
}

/* ---------- readProfile ---------- */

async function readProfile(fbUser) {
  const browserOffline =
    typeof navigator !== "undefined" && navigator.onLine === false;

  console.info(
    `[Auth] readProfile START uid=${fbUser.uid} email=${fbUser.email} offline=${browserOffline}`
  );

  // ── Phase 1: quick cache reads for all collections ─────────
  // These are synchronous-ish (IndexedDB) and never hang.
  let bestEffortProfile = null;
  for (const collectionName of PROFILE_COLLECTIONS) {
    const profileRef = doc(db, collectionName, fbUser.uid);
    try {
      const cached = await getDocFromCache(profileRef);
      if (cached?.exists()) {
        const p = makeProfile(cached, collectionName, "cache");
        if (firstCashierId(p.data) != null) {
          console.info(
            `[Auth] Profile from cache: ${collectionName}/${fbUser.uid}`
          );
          return p;
        }
        if (!bestEffortProfile) bestEffortProfile = p;
      }
    } catch {
      /* not in cache */
    }
  }

  if (browserOffline) {
    console.warn("[Auth] Browser offline — returning cached/best-effort only");
    return bestEffortProfile;
  }

  // ── Phase 2: CASHIER QUERY FIRST (this is what works) ──────
  // Resolves in ~200ms when a cashier doc exists for this email/uid.
  // Runs BEFORE the slow users/{uid} timeouts, so CashierID is set
  // as soon as possible.
  console.info("[Auth] Phase 2 START — querying cashier by Email/AuthUID");
  const queried = await queryCashierProfile(fbUser);
  if (queried && firstCashierId(queried.data) != null) {
    console.info(
      `[Auth] Phase 2 SUCCESS — CashierID=${firstCashierId(queried.data)}`
    );
    return queried;
  }
  console.warn("[Auth] Phase 2 miss — no cashier doc matched Email/AuthUID");

  // ── Phase 3: direct uid doc lookups (fallback, slow) ───────
  console.info("[Auth] Phase 3 START — direct uid doc lookups");
  for (const collectionName of PROFILE_COLLECTIONS) {
    const profileRef = doc(db, collectionName, fbUser.uid);
    const t0 = performance.now();
    try {
      const snapshot = await withTimeout(
        getDoc(profileRef),
        PROFILE_TIMEOUT_MS,
        `${collectionName}/${fbUser.uid}`
      );

      if (snapshot?.exists()) {
        const p = makeProfile(snapshot, collectionName, "server");
        if (firstCashierId(p.data) != null) {
          console.info(
            `[Auth] Profile from server: ${collectionName}/${fbUser.uid} in ${(
              performance.now() - t0
            ).toFixed(0)}ms`
          );
          return p;
        }
        if (!bestEffortProfile) bestEffortProfile = p;
        console.warn(
          `[Auth] ${collectionName}/${fbUser.uid} (server) exists but has no CashierID — continuing`
        );
      }
    } catch (error) {
      console.warn(
        `[Auth] Could not read ${collectionName}/${fbUser.uid} (${(
          performance.now() - t0
        ).toFixed(0)}ms):`,
        error?.message || error
      );
      // Never set networkDead here — a per-doc timeout is not "offline".
    }
  }

  if (bestEffortProfile) {
    console.warn(
      "[Auth] Returning best-effort profile with no CashierID — permissions will be empty.",
      bestEffortProfile.data
    );
  } else {
    console.warn(
      `[Auth] No profile document found for uid ${fbUser.uid} — cashier query and all direct reads missed.`
    );
  }
  return bestEffortProfile;
}

/* ---------- provider ---------- */

export function AuthProvider({ children }) {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [profileLoading, setProfileLoading] = useState(false);
  const [error, setError] = useState("");

  const activeUidRef = useRef(null);
  const fbUserRef = useRef(null);
  const userRef = useRef(null);

  useEffect(() => {
    userRef.current = user;
  }, [user]);

  const doRefreshProfile = useCallback(async (fbUser, { legacy, cached } = {}) => {
    if (!fbUser) return;

    setProfileLoading(true);
    try {
      const profileDoc = await readProfile(fbUser);
      if (activeUidRef.current !== fbUser.uid) return;

      if (!profileDoc) {
        setUser((prev) =>
          prev?.uid === fbUser.uid
            ? { ...prev, profileReady: prev.CashierID != null }
            : prev
        );
        return;
      }

      const prev = userRef.current;
      if (!prev || prev.uid !== fbUser.uid) return;

      const refreshed = buildUser(fbUser, {
        legacy,
        cache: cached,
        profileDoc,
      });

      const cashierId =
        refreshed.CashierID ?? normalizeCashierId(prev.CashierID);

      const finalUser = {
        ...prev,
        ...refreshed,
        CashierID: cashierId,
        profileReady: cashierId != null,
      };

      userRef.current = finalUser;
      setUser(finalUser);
      persistUser(finalUser);

      console.info("[Auth] Profile refresh complete:", {
        uid: fbUser.uid,
        source: `${profileDoc.collection}/${profileDoc.source}`,
        profileDocumentId: profileDoc.id,
        resolvedCashierID: cashierId,
      });

      if (cashierId == null) {
        console.warn(
          "[Auth] Profile found but CashierID is still null — doc payload follows.",
          profileDoc.data
        );
      }
    } catch (refreshError) {
      console.warn(
        "[Auth] Background profile refresh failed:",
        refreshError?.message || refreshError
      );
    } finally {
      if (activeUidRef.current === fbUser.uid) {
        setProfileLoading(false);
      }
    }
  }, []);

  const refreshProfileRef = useRef(doRefreshProfile);
  refreshProfileRef.current = doRefreshProfile;

  useEffect(() => {
    let disposed = false;

    const unsubscribe = onAuthStateChanged(auth, async (fbUser) => {
      if (!fbUser) {
        activeUidRef.current = null;
        fbUserRef.current = null;
        userRef.current = null;
        setUser(null);
        setProfileLoading(false);
        setLoading(false);
        return;
      }

      activeUidRef.current = fbUser.uid;
      fbUserRef.current = fbUser;

      const rawLegacy = readLegacyUser();
      const legacy = legacyMatchesAuthUser(rawLegacy, fbUser) ? rawLegacy : null;
      const cached = readCache(fbUser.uid);
      const initialUser = buildUser(fbUser, { legacy, cache: cached });

      if (disposed || activeUidRef.current !== fbUser.uid) return;

      const withReady = {
        ...initialUser,
        profileReady: initialUser.CashierID != null,
      };

      userRef.current = withReady;
      setUser(withReady);
      setLoading(false);
      setProfileLoading(true);

      if (withReady.CashierID != null) persistUser(withReady);

      console.info("[Auth] Initial identity:", {
        uid: fbUser.uid,
        email: fbUser.email,
        CashierID: initialUser.CashierID,
        legacyFound: Boolean(legacy),
        cacheFound: Boolean(cached),
      });

      doRefreshProfile(fbUser, { legacy, cached });
    });

    return () => {
      disposed = true;
      unsubscribe();
    };
  }, [doRefreshProfile]);

  useEffect(() => {
    const handleOnline = () => {
      const fbUser = fbUserRef.current;
      if (!fbUser) return;

      console.info("[Auth] Network restored — refreshing profile");
      const rawLegacy = readLegacyUser();
      const legacy = legacyMatchesAuthUser(rawLegacy, fbUser)
        ? rawLegacy
        : null;
      const cached = readCache(fbUser.uid);

      refreshProfileRef.current?.(fbUser, { legacy, cached });
    };

    window.addEventListener("online", handleOnline);
    return () => window.removeEventListener("online", handleOnline);
  }, []);

  const login = useCallback(async (email, password) => {
    setError("");
    try {
      const credential = await signInWithEmailAndPassword(
        auth,
        email.trim(),
        password
      );
      return credential.user;
    } catch (loginError) {
      const message = friendly(loginError);
      setError(message);
      throw new Error(message);
    }
  }, []);

  const logout = useCallback(async () => {
    const uid = auth.currentUser?.uid;
    clearLegacyUser();
    if (uid) clearCache(uid);

    activeUidRef.current = null;
    fbUserRef.current = null;
    userRef.current = null;
    setUser(null);
    setProfileLoading(false);
    setLoading(false);

    await signOut(auth);
  }, []);

  const value = useMemo(
    () => ({
      user,
      loading,
      profileLoading,
      error,
      login,
      logout,
      setError,
    }),
    [user, loading, profileLoading, error, login, logout]
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

function friendly(error) {
  switch (error?.code) {
    case "auth/invalid-credential":
    case "auth/wrong-password":
    case "auth/user-not-found":
      return "Wrong email or password.";
    case "auth/invalid-email":
      return "That email address is not valid.";
    case "auth/user-disabled":
      return "This account has been disabled.";
    case "auth/too-many-requests":
      return "Too many attempts. Please try again in a minute.";
    case "auth/network-request-failed":
      return "Network problem. Check your connection.";
    case "auth/operation-not-allowed":
      return "Email/Password sign-in is disabled in Firebase Console.";
    case "auth/invalid-api-key":
    case "auth/api-key-not-valid":
      return "Firebase config is missing or wrong (check .env).";
    default:
      return error?.message || "Login failed.";
  }
}