// CashOnHand.jsx
// ============================================================
// Cash on Hand — Firestore version
// ------------------------------------------------------------
// View and manage a cash account's ledger, plus record:
//   - Expenses
//   - Account transfers
//   - Supplier payments
//
// Firestore collections used:
//   - Accounts             (cash + expense accounts + balances)
//   - AccountTransactions  (ledger rows)
//   - SupplierPayments     (supplier payment log)
//
// Every write runs inside a `runFirestoreTransaction`:
//   1. Decrement source account StoredBalance
//   2. Increment destination account StoredBalance (transfer/expense)
//   3. Create matching AccountTransactions row(s)
//   4. Optionally create SupplierPayments row
// ============================================================

import React, {
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
} from "react";

import {
  doc,
  collection,
  serverTimestamp,
} from "firebase/firestore";

import {
  Plus,
  ArrowLeftRight,
  Building2,
  Calendar,
  Printer,
  Download,
  Bell,
  Filter,
  FileText,
  DollarSign,
  TrendingUp,
  TrendingDown,
  Search,
  X,
  RefreshCw,
  CheckCircle,
  AlertCircle,
} from "lucide-react";

import {
  COLLECTIONS,
  listCollection,
  runFirestoreTransaction,
} from "../lib/firestore.js";

import { db } from "../firebase.js";
import { AuthContext } from "../pos/SERVER/AuthContext.js";

/* =====================================================
   HELPERS
===================================================== */

function getToday() {
  const date = new Date();
  const pad = (n) => String(n).padStart(2, "0");
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(
    date.getDate()
  )}`;
}

function getDateBefore(days) {
  const date = new Date();
  date.setDate(date.getDate() - days);
  const pad = (n) => String(n).padStart(2, "0");
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(
    date.getDate()
  )}`;
}

function formatMoney(value) {
  return Number(value || 0).toLocaleString("en-LK", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  });
}

function formatDateTime(value) {
  if (!value) return "-";

  const date =
    typeof value?.toDate === "function" ? value.toDate() : new Date(value);

  if (Number.isNaN(date.getTime())) return typeof value === "string" ? value : "-";

  return date.toLocaleString("en-GB", {
    day: "2-digit",
    month: "2-digit",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  });
}

function toDateOnly(value) {
  if (!value) return null;
  const date =
    typeof value?.toDate === "function" ? value.toDate() : new Date(value);
  if (Number.isNaN(date.getTime())) return null;
  const pad = (n) => String(n).padStart(2, "0");
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(
    date.getDate()
  )}`;
}

/** Normalize a Firestore account doc. */
function normalizeAccount(raw) {
  const hasStored =
    raw.StoredBalance !== undefined ||
    raw.storedBalance !== undefined ||
    raw.balance !== undefined;

  return {
    ...raw,
    AccountID: raw.id ?? raw.AccountID ?? null,
    AccountName: raw.AccountName ?? raw.name ?? "",
    AccountType: raw.AccountType ?? raw.type ?? "",
    AccountNumber: raw.AccountNumber ?? raw.accountNumber ?? "",
    StoredBalance: Number(
      raw.StoredBalance ?? raw.storedBalance ?? raw.balance ?? 0
    ),
    HasStoredBalance: hasStored,
  };
}

/** Normalize a Firestore transaction doc. */
function normalizeTransaction(raw) {
  const rawDate = raw.TransactionDate ?? raw.date ?? null;

  return {
    TransactionID: raw.id ?? null,
    TransactionDate: rawDate,
    dateOnly: toDateOnly(rawDate),
    TransactionType: raw.TransactionType ?? raw.transactionType ?? "",
    Description: raw.Description ?? raw.description ?? "",
    ReferenceNo: raw.ReferenceNo ?? raw.referenceNo ?? "",
    Debit: Number(raw.Debit ?? raw.debit ?? 0),
    Credit: Number(raw.Credit ?? raw.credit ?? 0),
  };
}

/* =====================================================
   COMPONENT
===================================================== */

export default function CashOnHand() {
  const { user } = useContext(AuthContext);
  const username = user?.username || "admin";

  /* ---------- STATE ---------- */
  const [accounts, setAccounts] = useState([]);
  const [expenseAccounts, setExpenseAccounts] = useState([]);
  const [transactions, setTransactions] = useState([]);

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [message, setMessage] = useState("");
  const [messageType, setMessageType] = useState("success");

  const [selectedAccount, setSelectedAccount] = useState("");
  const [fromDate, setFromDate] = useState(getDateBefore(7));
  const [toDate, setToDate] = useState(getToday());
  const [filterType, setFilterType] = useState("All Transactions");

  const [activeTab, setActiveTab] = useState("statement");

  const [showExpense, setShowExpense] = useState(false);
  const [showTransfer, setShowTransfer] = useState(false);
  const [showSupplier, setShowSupplier] = useState(false);

  /* ---------- FORMS ---------- */
  const [expenseForm, setExpenseForm] = useState({
    AccountId: "",
    fAccountId: "",
    amount: "",
    description: "",
    referenceNo: "",
  });

  const [transferForm, setTransferForm] = useState({
    fromAccountId: "",
    toAccountId: "",
    amount: "",
    description: "",
    referenceNo: "",
  });

  const [supplierForm, setSupplierForm] = useState({
    amount: "",
    supplierName: "",
    description: "",
    referenceNo: "",
  });

  /* =====================================================
     MESSAGE
  ===================================================== */

  const showMessage = (text, type) => {
    setMessage(text);
    setMessageType(type);
    setTimeout(() => setMessage(""), 4000);
  };

  /* =====================================================
     LOAD ACCOUNTS + EXPENSE ACCOUNTS
  ===================================================== */

  const loadAccounts = useCallback(async () => {
    try {
      setError("");

      const rows = await listCollection(COLLECTIONS.ACCOUNTS, {
        where: [["IsDelete", "==", 0]],
      });

      const normalized = rows
        .map(normalizeAccount)
        .filter((a) => a.AccountID != null)
        .sort((a, b) =>
          String(a.AccountName).localeCompare(String(b.AccountName))
        );

      setAccounts(normalized);

      // Expense accounts = accounts with AccountType "expenses".
      // Fallback: if none defined, let the user pick any account.
      const expenseOnly = normalized.filter(
        (a) => String(a.AccountType).toLowerCase() === "expenses"
      );

      setExpenseAccounts(expenseOnly.length > 0 ? expenseOnly : normalized);

      // Preserve selection; auto-select first on initial load
      setSelectedAccount((prev) => {
        const stillExists = normalized.some(
          (a) => String(a.AccountID) === String(prev)
        );
        if (prev && stillExists) return prev;
        return normalized.length > 0 ? String(normalized[0].AccountID) : "";
      });
    } catch (err) {
      console.error("loadAccounts error:", err);
      setAccounts([]);
      setSelectedAccount("");
      setError(err.message || "Unable to load cash accounts.");
    }
  }, []);

  /* =====================================================
     LOAD TRANSACTIONS
     -----------------------------------------------------
     Loads ALL transactions for the account (no date filter)
     so opening balance can be computed accurately. Date and
     type filters are applied client-side.
  ===================================================== */

  const loadTransactions = useCallback(async () => {
    if (!selectedAccount) {
      setTransactions([]);
      return;
    }

    try {
      setLoading(true);
      setError("");

      const rows = await listCollection(COLLECTIONS.ACCOUNT_TRANSACTIONS, {
        where: [
          ["AccountID", "==", selectedAccount],
          ["IsDelete", "==", 0],
        ],
      });

      const normalized = rows
        .map(normalizeTransaction)
        .filter((t) => t.TransactionID)
        .sort((a, b) =>
          (a.dateOnly || "") < (b.dateOnly || "")
            ? -1
            : (a.dateOnly || "") > (b.dateOnly || "")
            ? 1
            : 0
        );

      setTransactions(normalized);
    } catch (err) {
      console.error("loadTransactions error:", err);
      setError(err.message || "Unable to load transactions.");
      setTransactions([]);
    } finally {
      setLoading(false);
    }
  }, [selectedAccount]);

  /* ---------- INITIAL LOAD ---------- */
  useEffect(() => {
    loadAccounts();
  }, [loadAccounts]);

  useEffect(() => {
    if (selectedAccount) loadTransactions();
  }, [loadTransactions, selectedAccount]);

  /* =====================================================
     SELECTED ACCOUNT
  ===================================================== */

  const selectedAccountData = useMemo(
    () =>
      accounts.find(
        (account) => String(account.AccountID) === String(selectedAccount)
      ),
    [accounts, selectedAccount]
  );

  /* =====================================================
     SUMMARY
     -----------------------------------------------------
     Period transactions are filtered client-side by date
     and type. Opening balance = StoredBalance − netMovement
     so the closing running balance equals the current
     balance shown in the header.
  ===================================================== */

  const summary = useMemo(() => {
    const fromStr = fromDate || "";
    const toStr = toDate || "";

    const periodTx = transactions.filter((t) => {
      if (!t.dateOnly) return false;
      if (fromStr && t.dateOnly < fromStr) return false;
      if (toStr && t.dateOnly > toStr) return false;
      return true;
    });

    const filtered =
      filterType === "Credit" || filterType === "credit"
        ? periodTx.filter((t) => t.Credit > 0)
        : filterType === "Debit" || filterType === "debit"
        ? periodTx.filter((t) => t.Debit > 0)
        : periodTx;

    const credits = filtered.reduce(
      (total, item) => total + Number(item.Credit || 0),
      0
    );
    const debits = filtered.reduce(
      (total, item) => total + Number(item.Debit || 0),
      0
    );
    const netMovement = credits - debits;

    const storedBalance = Number(selectedAccountData?.StoredBalance ?? 0);
    const hasStored = selectedAccountData?.HasStoredBalance === true;

    // Same formula as original: opening = stored − periodMovement
    const openingBalance = storedBalance - netMovement;
    const currentBalance = hasStored
      ? storedBalance
      : openingBalance + netMovement;

    return {
      credits,
      debits,
      netMovement,
      openingBalance,
      balance: currentBalance,
      calculatedBalance: openingBalance + netMovement,
      count: filtered.length,
      periodTransactions: filtered, // pre-sorted, ready to render
    };
  }, [transactions, filterType, fromDate, toDate, selectedAccountData]);

  /* =====================================================
     REFRESH AFTER MUTATION
  ===================================================== */

  const refreshAfterMutation = async () => {
    await Promise.all([loadAccounts(), loadTransactions()]);
  };

  /* =====================================================
     SAVE EXPENSE
     -----------------------------------------------------
     - Debit the source cash account (money out)
     - Credit the destination expense account
     - Create 2 AccountTransactions
  ===================================================== */

  async function saveExpense(e) {
    e.preventDefault();

    if (!expenseForm.AccountId) {
      showMessage("Please select an expense account.", "error");
      return;
    }
    if (!expenseForm.fAccountId) {
      showMessage("Please select a cash account.", "error");
      return;
    }
    if (
      String(expenseForm.AccountId) === String(expenseForm.fAccountId)
    ) {
      showMessage("From and To accounts must be different.", "error");
      return;
    }

    const amount = Number(expenseForm.amount);
    if (!Number.isFinite(amount) || amount <= 0) {
      showMessage("Please enter a valid amount.", "error");
      return;
    }

    try {
      setLoading(true);

      await runFirestoreTransaction(async (tx) => {
        // Read both accounts
        const fromRef = doc(db, COLLECTIONS.ACCOUNTS, expenseForm.fAccountId);
        const toRef = doc(db, COLLECTIONS.ACCOUNTS, expenseForm.AccountId);
        const fromSnap = await tx.get(fromRef);
        const toSnap = await tx.get(toRef);

        if (!fromSnap.exists()) throw new Error("Cash account not found.");
        if (!toSnap.exists()) throw new Error("Expense account not found.");

        const from = fromSnap.data();
        const to = toSnap.data();

        // Update balances
        tx.update(fromRef, {
          StoredBalance: Number(from.StoredBalance || 0) - amount,
          ModifiedAt: serverTimestamp(),
          ModifiedBy: username,
        });
        tx.update(toRef, {
          StoredBalance: Number(to.StoredBalance || 0) + amount,
          ModifiedAt: serverTimestamp(),
          ModifiedBy: username,
        });

        // DEBIT from cash source
        const debitRef = doc(
          collection(db, COLLECTIONS.ACCOUNT_TRANSACTIONS)
        );
        tx.set(debitRef, {
          AccountID: expenseForm.fAccountId,
          AccountName: from.AccountName || "",
          AccountType: from.AccountType || "",
          DetailType: from.DetailType || "",
          TransactionDate: new Date().toISOString(),
          TransactionType: "Expense",
          Description:
            expenseForm.description ||
            `Expense to ${to.AccountName || "expense account"}`,
          ReferenceNo: expenseForm.referenceNo || "",
          Debit: amount,
          Credit: 0,
          IsReconciled: 0,
          IsDelete: 0,
          CreatedAt: serverTimestamp(),
          CreatedBy: username,
        });

        // CREDIT to expense account
        const creditRef = doc(
          collection(db, COLLECTIONS.ACCOUNT_TRANSACTIONS)
        );
        tx.set(creditRef, {
          AccountID: expenseForm.AccountId,
          AccountName: to.AccountName || "",
          AccountType: to.AccountType || "",
          DetailType: to.DetailType || "",
          TransactionDate: new Date().toISOString(),
          TransactionType: "Expense",
          Description:
            expenseForm.description ||
            `Expense from ${from.AccountName || "cash account"}`,
          ReferenceNo: expenseForm.referenceNo || "",
          Debit: 0,
          Credit: amount,
          IsReconciled: 0,
          IsDelete: 0,
          CreatedAt: serverTimestamp(),
          CreatedBy: username,
        });
      });

      showMessage("Expense saved successfully", "success");

      setExpenseForm({
        AccountId: "",
        fAccountId: "",
        amount: "",
        description: "",
        referenceNo: "",
      });
      setShowExpense(false);

      await refreshAfterMutation();
    } catch (err) {
      console.error("saveExpense error:", err);
      showMessage(err.message || "Unable to save expense", "error");
    } finally {
      setLoading(false);
    }
  }

  /* =====================================================
     SAVE TRANSFER
     -----------------------------------------------------
     - Debit source (money out)
     - Credit destination (money in)
     - Create 2 AccountTransactions + 1 AccountTransfers
  ===================================================== */

  async function saveTransfer(e) {
    e.preventDefault();

    if (!transferForm.fromAccountId || !transferForm.toAccountId) {
      showMessage("Please select both accounts.", "error");
      return;
    }
    if (transferForm.fromAccountId === transferForm.toAccountId) {
      showMessage("From Account and To Account cannot be the same.", "error");
      return;
    }

    const amount = Number(transferForm.amount);
    if (!Number.isFinite(amount) || amount <= 0) {
      showMessage("Please enter a valid amount.", "error");
      return;
    }

    try {
      setLoading(true);

      await runFirestoreTransaction(async (tx) => {
        const fromRef = doc(db, COLLECTIONS.ACCOUNTS, transferForm.fromAccountId);
        const toRef = doc(db, COLLECTIONS.ACCOUNTS, transferForm.toAccountId);
        const fromSnap = await tx.get(fromRef);
        const toSnap = await tx.get(toRef);

        if (!fromSnap.exists()) throw new Error("Source account not found.");
        if (!toSnap.exists()) throw new Error("Destination account not found.");

        const from = fromSnap.data();
        const to = toSnap.data();
        const fromBalance = Number(from.StoredBalance || 0);

        if (fromBalance < amount) {
          throw new Error(
            `Insufficient funds in ${from.AccountName || "source"} (Rs.${formatMoney(
              fromBalance
            )}).`
          );
        }

        // Update balances
        tx.update(fromRef, {
          StoredBalance: fromBalance - amount,
          ModifiedAt: serverTimestamp(),
          ModifiedBy: username,
        });
        tx.update(toRef, {
          StoredBalance: Number(to.StoredBalance || 0) + amount,
          ModifiedAt: serverTimestamp(),
          ModifiedBy: username,
        });

        // Transfer record
        const transferRef = doc(db, COLLECTIONS.ACCOUNT_TRANSFERS);
        tx.set(transferRef, {
          FromAccountID: transferForm.fromAccountId,
          FromAccountName: from.AccountName || "",
          ToAccountID: transferForm.toAccountId,
          ToAccountName: to.AccountName || "",
          Amount: amount,
          Description: transferForm.description || "",
          ReferenceNo: transferForm.referenceNo || "",
          TransferDate: new Date().toISOString(),
          CreatedAt: serverTimestamp(),
          CreatedBy: username,
          IsDelete: 0,
        });

        // DEBIT from source
        const debitRef = doc(
          collection(db, COLLECTIONS.ACCOUNT_TRANSACTIONS)
        );
        tx.set(debitRef, {
          AccountID: transferForm.fromAccountId,
          AccountName: from.AccountName || "",
          AccountType: from.AccountType || "",
          DetailType: from.DetailType || "",
          TransactionDate: new Date().toISOString(),
          TransactionType: "Transfer Out",
          Description:
            transferForm.description ||
            `Transfer to ${to.AccountName || "account"}`,
          ReferenceNo: transferForm.referenceNo || "",
          Debit: amount,
          Credit: 0,
          IsReconciled: 0,
          IsDelete: 0,
          CreatedAt: serverTimestamp(),
          CreatedBy: username,
        });

        // CREDIT to destination
        const creditRef = doc(
          collection(db, COLLECTIONS.ACCOUNT_TRANSACTIONS)
        );
        tx.set(creditRef, {
          AccountID: transferForm.toAccountId,
          AccountName: to.AccountName || "",
          AccountType: to.AccountType || "",
          DetailType: to.DetailType || "",
          TransactionDate: new Date().toISOString(),
          TransactionType: "Transfer In",
          Description:
            transferForm.description ||
            `Transfer from ${from.AccountName || "account"}`,
          ReferenceNo: transferForm.referenceNo || "",
          Debit: 0,
          Credit: amount,
          IsReconciled: 0,
          IsDelete: 0,
          CreatedAt: serverTimestamp(),
          CreatedBy: username,
        });
      });

      showMessage("Transfer completed successfully", "success");

      setTransferForm({
        fromAccountId: "",
        toAccountId: "",
        amount: "",
        description: "",
        referenceNo: "",
      });
      setShowTransfer(false);

      await refreshAfterMutation();
    } catch (err) {
      console.error("saveTransfer error:", err);
      showMessage(err.message || "Unable to complete transfer", "error");
    } finally {
      setLoading(false);
    }
  }

  /* =====================================================
     SAVE SUPPLIER PAYMENT
     -----------------------------------------------------
     - Debit the selected cash account
     - Create 1 AccountTransaction
     - Create 1 SupplierPayments record
  ===================================================== */

  async function saveSupplierPayment(e) {
    e.preventDefault();

    if (!supplierForm.supplierName.trim()) {
      showMessage("Supplier name is required.", "error");
      return;
    }

    const amount = Number(supplierForm.amount);
    if (!Number.isFinite(amount) || amount <= 0) {
      showMessage("Please enter a valid amount.", "error");
      return;
    }

    try {
      setLoading(true);

      await runFirestoreTransaction(async (tx) => {
        const accountRef = doc(db, COLLECTIONS.ACCOUNTS, selectedAccount);
        const accountSnap = await tx.get(accountRef);

        if (!accountSnap.exists()) throw new Error("Cash account not found.");

        const account = accountSnap.data();
        const currentBalance = Number(account.StoredBalance || 0);

        if (currentBalance < amount) {
          throw new Error(
            `Insufficient funds in ${account.AccountName || "account"} (Rs.${formatMoney(
              currentBalance
            )}).`
          );
        }

        // Update balance
        tx.update(accountRef, {
          StoredBalance: currentBalance - amount,
          ModifiedAt: serverTimestamp(),
          ModifiedBy: username,
        });

        // DEBIT transaction
        const txRef = doc(collection(db, COLLECTIONS.ACCOUNT_TRANSACTIONS));
        tx.set(txRef, {
          AccountID: selectedAccount,
          AccountName: account.AccountName || "",
          AccountType: account.AccountType || "",
          DetailType: account.DetailType || "",
          TransactionDate: new Date().toISOString(),
          TransactionType: "Supplier Payment",
          Description:
            supplierForm.description ||
            `Payment to ${supplierForm.supplierName}`,
          ReferenceNo: supplierForm.referenceNo || "",
          Debit: amount,
          Credit: 0,
          IsReconciled: 0,
          IsDelete: 0,
          CreatedAt: serverTimestamp(),
          CreatedBy: username,
        });

        // SupplierPayments record
        const payRef = doc(collection(db, "SupplierPayments"));
        tx.set(payRef, {
          SupplierName: supplierForm.supplierName.trim(),
          Amount: amount,
          PaymentDate: new Date().toISOString(),
          PaymentMethod: "Cash",
          ReferenceNo: supplierForm.referenceNo || null,
          Remark: supplierForm.description || null,
          AccountID: selectedAccount,
          AccountName: account.AccountName || "",
          CreatedAt: serverTimestamp(),
          CreatedBy: username,
          IsDelete: 0,
        });
      });

      showMessage("Supplier payment saved successfully", "success");

      setSupplierForm({
        amount: "",
        supplierName: "",
        description: "",
        referenceNo: "",
      });
      setShowSupplier(false);

      await refreshAfterMutation();
    } catch (err) {
      console.error("saveSupplierPayment error:", err);
      showMessage(err.message || "Unable to save supplier payment", "error");
    } finally {
      setLoading(false);
    }
  }

  /* =====================================================
     QUICK ACTIONS
  ===================================================== */

  function setToday() {
    setFromDate(getToday());
    setToDate(getToday());
  }

  function printReport() {
    window.print();
  }

  function exportCSV() {
    if (!summary.periodTransactions.length) {
      showMessage("No transactions to export.", "error");
      return;
    }

    const headers = [
      "Date",
      "Type",
      "Description",
      "Debit",
      "Credit",
      "Balance",
      "Reference",
    ];

    let runningBalance = Number(summary.openingBalance || 0);

    const rows = summary.periodTransactions.map((item) => {
      const debit = Number(item.Debit || 0);
      const credit = Number(item.Credit || 0);
      runningBalance += credit - debit;

      return [
        formatDateTime(item.TransactionDate),
        item.TransactionType || "",
        item.Description || "",
        debit.toFixed(2),
        credit.toFixed(2),
        runningBalance.toFixed(2),
        item.ReferenceNo || "",
      ];
    });

    const csv = [headers, ...rows]
      .map((row) =>
        row
          .map(
            (value) => `"${String(value).replace(/"/g, '""')}"`
          )
          .join(",")
      )
      .join("\n");

    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `cash-statement-${fromDate}-${toDate}.csv`;
    link.click();
    URL.revokeObjectURL(url);
  }

  function openExpenseModal() {
    setExpenseForm({
      AccountId: "",
      fAccountId: "",
      amount: "",
      description: "",
      referenceNo: "",
    });
    setShowExpense(true);
  }

  /* =====================================================
     RENDER
  ===================================================== */

  return (
    <div className="min-h-screen bg-white text-slate-900">
      {/* ==================== HEADER ==================== */}
      <div className="px-7 pt-7">
        <div className="flex flex-col gap-5 lg:flex-row lg:items-center lg:justify-between">
          <div>
            <h1 className="text-3xl font-bold">Cash on Hand</h1>
            <p className="mt-1 text-slate-500">
              View detailed cash on hand account statements
            </p>
          </div>

          <div className="flex flex-wrap gap-2">
            <button
              onClick={openExpenseModal}
              className="flex items-center gap-2 rounded-xl border border-slate-200 bg-white px-4 py-2.5 text-sm font-medium shadow-sm hover:bg-slate-50"
            >
              <Plus size={17} />
              Add Expense
            </button>

            <button
              onClick={() => setShowTransfer(true)}
              className="flex items-center gap-2 rounded-xl bg-amber-500 px-4 py-2.5 text-sm font-semibold text-white shadow-sm hover:bg-amber-600"
            >
              <ArrowLeftRight size={17} />
              Add Transfer
            </button>

            <button
              onClick={() => setShowSupplier(true)}
              className="flex items-center gap-2 rounded-xl border border-slate-200 bg-white px-4 py-2.5 text-sm font-medium shadow-sm hover:bg-slate-50"
            >
              <Building2 size={17} />
              Supplier Payment
            </button>

            <button
              onClick={setToday}
              className="flex items-center gap-2 rounded-xl border border-slate-200 bg-white px-4 py-2.5 text-sm font-medium shadow-sm hover:bg-slate-50"
            >
              <Calendar size={17} />
              Today
            </button>

            <button
              onClick={printReport}
              className="flex items-center gap-2 rounded-xl border border-slate-200 bg-white px-4 py-2.5 text-sm font-medium shadow-sm hover:bg-slate-50"
            >
              <Printer size={17} />
              Print Report
            </button>

            <button
              onClick={exportCSV}
              className="flex items-center gap-2 rounded-xl border border-slate-200 bg-white px-4 py-2.5 text-sm font-medium shadow-sm hover:bg-slate-50"
            >
              <Download size={17} />
              Export CSV
            </button>

            <button className="flex items-center gap-2 rounded-xl border border-slate-200 bg-white px-4 py-2.5 text-sm font-medium shadow-sm hover:bg-slate-50">
              <Bell size={17} />
              Price Updates
            </button>
          </div>
        </div>

        {/* TABS */}
        <div className="mt-6 flex w-fit rounded-xl bg-slate-100 p-1">
          <button
            onClick={() => setActiveTab("statement")}
            className={`rounded-lg px-5 py-2 text-sm font-medium ${
              activeTab === "statement"
                ? "bg-white shadow-sm"
                : "text-slate-500"
            }`}
          >
            Statement
          </button>
          <button
            onClick={() => setActiveTab("summary")}
            className={`rounded-lg px-5 py-2 text-sm font-medium ${
              activeTab === "summary" ? "bg-white shadow-sm" : "text-slate-500"
            }`}
          >
            Summary
          </button>
        </div>
      </div>

      {/* ==================== MESSAGES ==================== */}
      {message && (
        <div className="mx-7 mt-5">
          <div
            className={`flex items-center gap-3 rounded-xl border px-4 py-3 ${
              messageType === "success"
                ? "border-green-200 bg-green-50 text-green-700"
                : "border-red-200 bg-red-50 text-red-700"
            }`}
          >
            {messageType === "success" ? (
              <CheckCircle size={18} />
            ) : (
              <AlertCircle size={18} />
            )}
            {message}
          </div>
        </div>
      )}

      {error && (
        <div className="mx-7 mt-5">
          <div className="flex items-center gap-3 rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-red-700">
            <AlertCircle size={18} />
            {error}
          </div>
        </div>
      )}

      {/* ==================== FILTERS ==================== */}
      <div className="mx-7 mt-6 rounded-2xl border border-slate-200 bg-white p-5 shadow-sm">
        <div className="mb-5 flex items-center gap-2">
          <Filter size={20} />
          <h2 className="text-xl font-semibold">Filters</h2>
        </div>

        <div className="grid grid-cols-1 gap-5 md:grid-cols-2 xl:grid-cols-4">
          <div>
            <label className="mb-2 block text-sm font-medium">
              Cash Account
            </label>
            <select
              value={selectedAccount}
              onChange={(e) => setSelectedAccount(e.target.value)}
              className="w-full rounded-xl border border-slate-200 bg-white px-4 py-3 outline-none focus:border-amber-500"
            >
              <option value="">Select Cash Account</option>
              {accounts.map((account) => (
                <option key={account.AccountID} value={account.AccountID}>
                  {account.AccountName}
                </option>
              ))}
            </select>
          </div>

          <div>
            <label className="mb-2 block text-sm font-medium">From Date</label>
            <input
              type="date"
              value={fromDate}
              onChange={(e) => setFromDate(e.target.value)}
              className="w-full rounded-xl border border-slate-200 px-4 py-3 outline-none focus:border-amber-500"
            />
          </div>

          <div>
            <label className="mb-2 block text-sm font-medium">To Date</label>
            <input
              type="date"
              value={toDate}
              onChange={(e) => setToDate(e.target.value)}
              className="w-full rounded-xl border border-slate-200 px-4 py-3 outline-none focus:border-amber-500"
            />
          </div>

          <div>
            <label className="mb-2 block text-sm font-medium">Filter Type</label>
            <select
              value={filterType}
              onChange={(e) => setFilterType(e.target.value)}
              className="w-full rounded-xl border border-slate-200 bg-white px-4 py-3 outline-none focus:border-amber-500"
            >
              <option value="All Transactions">All Transactions</option>
              <option value="Expense">Expense</option>
              <option value="Transfer">Transfer</option>
              <option value="Supplier Payment">Supplier Payment</option>
            </select>
          </div>
        </div>
      </div>

      {/* ==================== SUMMARY CARDS ==================== */}
      <div className="mx-7 mt-5 grid grid-cols-1 gap-4 md:grid-cols-2 xl:grid-cols-4">
        <SummaryCard
          icon={<DollarSign size={20} />}
          title="Current Balance"
          value={summary.balance}
          className="text-blue-600"
        />
        <SummaryCard
          icon={<TrendingUp size={20} />}
          title="Total Credits"
          value={summary.credits}
          className="text-green-600"
        />
        <SummaryCard
          icon={<TrendingDown size={20} />}
          title="Total Debits"
          value={summary.debits}
          className="text-red-600"
        />
        <SummaryCard
          icon={<FileText size={20} />}
          title="Transactions"
          value={summary.count}
          number
          className="text-purple-600"
        />
      </div>

      {/* ==================== STATEMENT TAB ==================== */}
      {activeTab === "statement" && (
        <div className="mx-7 mt-5 mb-10 rounded-2xl border border-slate-200 bg-white shadow-sm">
          <div className="border-b border-slate-200 px-6 py-5">
            <div className="flex flex-col gap-3 md:flex-row md:items-center md:justify-between">
              <div className="flex items-center gap-3">
                <FileText size={22} className="text-slate-700" />
                <div>
                  <h2 className="text-xl font-semibold">
                    Statement
                    {selectedAccountData
                      ? ` - ${selectedAccountData.AccountName}`
                      : ""}
                    {selectedAccountData?.AccountNumber
                      ? ` - ${selectedAccountData.AccountNumber}`
                      : ""}
                  </h2>
                  <p className="text-sm text-slate-500">
                    {fromDate} → {toDate}
                  </p>
                </div>
              </div>

              <button
                onClick={refreshAfterMutation}
                className="flex items-center justify-center gap-2 rounded-xl border border-slate-200 px-4 py-2 text-sm hover:bg-slate-50"
              >
                <RefreshCw
                  size={16}
                  className={loading ? "animate-spin" : ""}
                />
                Refresh
              </button>
            </div>
          </div>

          <div className="overflow-x-auto">
            <table className="w-full min-w-[1000px] text-sm">
              <thead className="bg-slate-50">
                <tr>
                  <th className="px-5 py-4 text-left font-semibold text-slate-600">
                    Date
                  </th>
                  <th className="px-5 py-4 text-left font-semibold text-slate-600">
                    Type
                  </th>
                  <th className="px-5 py-4 text-left font-semibold text-slate-600">
                    Description
                  </th>
                  <th className="px-5 py-4 text-right font-semibold text-slate-600">
                    Amount
                  </th>
                  <th className="px-5 py-4 text-right font-semibold text-slate-600">
                    Balance
                  </th>
                  <th className="px-5 py-4 text-left font-semibold text-slate-600">
                    Reference
                  </th>
                </tr>
              </thead>

              <tbody>
                {loading && (
                  <tr>
                    <td colSpan="6" className="py-12 text-center">
                      <RefreshCw
                        size={25}
                        className="mx-auto animate-spin text-amber-500"
                      />
                      <p className="mt-3 text-slate-500">
                        Loading transactions...
                      </p>
                    </td>
                  </tr>
                )}

                {!loading && summary.periodTransactions.length === 0 && (
                  <tr>
                    <td
                      colSpan="6"
                      className="py-12 text-center text-slate-500"
                    >
                      <Search size={30} className="mx-auto mb-3" />
                      No transactions found for the selected filters.
                    </td>
                  </tr>
                )}

                {!loading && summary.periodTransactions.length > 0 && (
                  <>
                    <tr className="border-t border-slate-100 bg-slate-50">
                      <td
                        colSpan="4"
                        className="px-5 py-3 text-sm font-semibold text-slate-700"
                      >
                        Opening Balance
                      </td>
                      <td className="px-5 py-3 text-right font-mono text-sm font-semibold text-slate-700">
                        Rs.{formatMoney(summary.openingBalance)}
                      </td>
                      <td></td>
                    </tr>

                    {(() => {
                      let runningBalance = Number(
                        summary.openingBalance || 0
                      );

                      return summary.periodTransactions.map((item) => {
                        const debit = Number(item.Debit || 0);
                        const credit = Number(item.Credit || 0);
                        runningBalance += credit - debit;

                        const isCredit = credit > 0;
                        const amount = isCredit ? credit : debit;

                        return (
                          <tr
                            key={item.TransactionID}
                            className="border-t border-slate-100 hover:bg-slate-50"
                          >
                            <td className="whitespace-nowrap px-5 py-4">
                              {formatDateTime(item.TransactionDate)}
                            </td>
                            <td className="px-5 py-4">
                              <TransactionBadge type={item.TransactionType} />
                            </td>
                            <td className="max-w-[400px] px-5 py-4">
                              <div className="truncate">
                                {item.Description || "-"}
                              </div>
                            </td>
                            <td
                              className={`px-5 py-4 text-right font-semibold ${
                                isCredit ? "text-green-600" : "text-red-600"
                              }`}
                            >
                              {isCredit ? "+" : "-"} Rs.
                              {formatMoney(amount)}
                            </td>
                            <td
                              className={`px-5 py-4 text-right font-mono font-semibold ${
                                runningBalance < 0
                                  ? "text-red-600"
                                  : "text-slate-900"
                              }`}
                            >
                              Rs.{formatMoney(runningBalance)}
                            </td>
                            <td className="px-5 py-4 text-slate-500">
                              {item.ReferenceNo || "-"}
                            </td>
                          </tr>
                        );
                      });
                    })()}
                  </>
                )}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* ==================== SUMMARY TAB ==================== */}
      {activeTab === "summary" && (
        <div className="mx-7 mt-5 mb-10 rounded-2xl border border-slate-200 p-6">
          <h2 className="text-xl font-semibold">Cash Summary</h2>

          <div className="mt-5 grid gap-5 md:grid-cols-2 xl:grid-cols-4">
            <div className="rounded-xl bg-green-50 p-5">
              <p className="text-sm text-green-700">Total Money In</p>
              <p className="mt-2 text-2xl font-bold text-green-700">
                Rs.{formatMoney(summary.credits)}
              </p>
            </div>

            <div className="rounded-xl bg-red-50 p-5">
              <p className="text-sm text-red-700">Total Money Out</p>
              <p className="mt-2 text-2xl font-bold text-red-700">
                Rs.{formatMoney(summary.debits)}
              </p>
            </div>

            <div className="rounded-xl bg-slate-100 p-5">
              <p className="text-sm text-slate-700">Period Movement</p>
              <p
                className={`mt-2 text-2xl font-bold ${
                  summary.netMovement < 0 ? "text-red-600" : "text-green-700"
                }`}
              >
                Rs.{formatMoney(summary.netMovement)}
              </p>
            </div>

            <div className="rounded-xl bg-blue-50 p-5">
              <p className="text-sm text-blue-700">
                Net Cash (Current Balance)
              </p>
              <p className="mt-2 text-2xl font-bold text-blue-700">
                Rs.{formatMoney(summary.balance)}
              </p>
            </div>
          </div>
        </div>
      )}

      {/* ==================== EXPENSE MODAL ==================== */}
      {showExpense && (
        <Modal title="Add Expense" onClose={() => setShowExpense(false)}>
          <form onSubmit={saveExpense} className="space-y-4">
            <div>
              <label className="mb-2 block text-sm font-medium">
                Cash Account <span className="text-red-500">*</span>
              </label>
              <select
                value={expenseForm.fAccountId}
                onChange={(e) =>
                  setExpenseForm({ ...expenseForm, fAccountId: e.target.value })
                }
                required
                className="w-full rounded-xl border border-slate-200 px-4 py-3"
              >
                <option value="">Select account</option>
                {accounts.map((account) => (
                  <option key={account.AccountID} value={account.AccountID}>
                    {account.AccountName}
                  </option>
                ))}
              </select>
            </div>

            <div>
              <label className="mb-2 block text-sm font-medium">
                Expense Account <span className="text-red-500">*</span>
              </label>
              <select
                value={expenseForm.AccountId}
                onChange={(e) =>
                  setExpenseForm({ ...expenseForm, AccountId: e.target.value })
                }
                required
                className="w-full rounded-xl border border-slate-200 bg-white px-4 py-3 outline-none focus:border-amber-500"
              >
                <option value="">Select Expense Account</option>
                {expenseAccounts.map((account) => (
                  <option key={account.AccountID} value={account.AccountID}>
                    {account.AccountName}
                  </option>
                ))}
              </select>
            </div>

            <FormInput
              label="Amount"
              type="number"
              value={expenseForm.amount}
              onChange={(value) =>
                setExpenseForm({ ...expenseForm, amount: value })
              }
              required
            />

            <FormInput
              label="Description"
              value={expenseForm.description}
              onChange={(value) =>
                setExpenseForm({ ...expenseForm, description: value })
              }
              placeholder="Description"
            />

            <FormInput
              label="Reference No"
              value={expenseForm.referenceNo}
              onChange={(value) =>
                setExpenseForm({ ...expenseForm, referenceNo: value })
              }
            />

            <ModalButtons
              onCancel={() => setShowExpense(false)}
              loading={loading}
            />
          </form>
        </Modal>
      )}

      {/* ==================== TRANSFER MODAL ==================== */}
      {showTransfer && (
        <Modal title="Add Transfer" onClose={() => setShowTransfer(false)}>
          <form onSubmit={saveTransfer} className="space-y-4">
            <div>
              <label className="mb-2 block text-sm font-medium">
                From Account
              </label>
              <select
                value={transferForm.fromAccountId}
                onChange={(e) =>
                  setTransferForm({
                    ...transferForm,
                    fromAccountId: e.target.value,
                  })
                }
                required
                className="w-full rounded-xl border border-slate-200 px-4 py-3"
              >
                <option value="">Select account</option>
                {accounts.map((account) => (
                  <option key={account.AccountID} value={account.AccountID}>
                    {account.AccountName}
                  </option>
                ))}
              </select>
            </div>

            <div>
              <label className="mb-2 block text-sm font-medium">
                To Account
              </label>
              <select
                value={transferForm.toAccountId}
                onChange={(e) =>
                  setTransferForm({
                    ...transferForm,
                    toAccountId: e.target.value,
                  })
                }
                required
                className="w-full rounded-xl border border-slate-200 px-4 py-3"
              >
                <option value="">Select account</option>
                {accounts
                  .filter(
                    (a) =>
                      String(a.AccountID) !==
                      String(transferForm.fromAccountId)
                  )
                  .map((account) => (
                    <option key={account.AccountID} value={account.AccountID}>
                      {account.AccountName}
                    </option>
                  ))}
              </select>
            </div>

            <FormInput
              label="Amount"
              type="number"
              value={transferForm.amount}
              onChange={(value) =>
                setTransferForm({ ...transferForm, amount: value })
              }
              required
            />

            <FormInput
              label="Description"
              value={transferForm.description}
              onChange={(value) =>
                setTransferForm({ ...transferForm, description: value })
              }
            />

            <FormInput
              label="Reference No"
              value={transferForm.referenceNo}
              onChange={(value) =>
                setTransferForm({ ...transferForm, referenceNo: value })
              }
            />

            <ModalButtons
              onCancel={() => setShowTransfer(false)}
              loading={loading}
            />
          </form>
        </Modal>
      )}

      {/* ==================== SUPPLIER PAYMENT MODAL ==================== */}
      {showSupplier && (
        <Modal
          title="Supplier Payment"
          onClose={() => setShowSupplier(false)}
        >
          <form onSubmit={saveSupplierPayment} className="space-y-4">
            <FormInput
              label="Supplier Name"
              value={supplierForm.supplierName}
              onChange={(value) =>
                setSupplierForm({ ...supplierForm, supplierName: value })
              }
              required
            />

            <FormInput
              label="Amount"
              type="number"
              value={supplierForm.amount}
              onChange={(value) =>
                setSupplierForm({ ...supplierForm, amount: value })
              }
              required
            />

            <FormInput
              label="Description"
              value={supplierForm.description}
              onChange={(value) =>
                setSupplierForm({ ...supplierForm, description: value })
              }
            />

            <FormInput
              label="Reference No"
              value={supplierForm.referenceNo}
              onChange={(value) =>
                setSupplierForm({ ...supplierForm, referenceNo: value })
              }
            />

            <ModalButtons
              onCancel={() => setShowSupplier(false)}
              loading={loading}
            />
          </form>
        </Modal>
      )}
    </div>
  );
}

/* =====================================================
   REUSABLE COMPONENTS
===================================================== */

function SummaryCard({ icon, title, value, className, number }) {
  return (
    <div className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm">
      <div className="flex items-center gap-3">
        <div className={className}>{icon}</div>
        <span className="text-sm text-slate-500">{title}</span>
      </div>

      <p
        className={`mt-2 text-2xl font-bold ${
          number ? "text-slate-900" : ""
        }`}
      >
        {number ? value : `Rs.${formatMoney(value)}`}
      </p>
    </div>
  );
}

function TransactionBadge({ type }) {
  let style = "bg-slate-100 text-slate-700";

  if (type === "Expense" || type === "DEBIT" || type === "Transfer Out") {
    style = "bg-red-50 text-red-700";
  } else if (type === "Transfer" || type === "Transfer In") {
    style = "bg-amber-50 text-amber-700";
  } else if (type === "Supplier Payment") {
    style = "bg-purple-50 text-purple-700";
  } else if (type === "Credit" || type === "CREDIT") {
    style = "bg-green-50 text-green-700";
  }

  return (
    <span className={`rounded-full px-3 py-1 text-xs font-semibold ${style}`}>
      {type || "Transaction"}
    </span>
  );
}

function Modal({ title, children, onClose }) {
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 p-4">
      <div className="w-full max-w-lg rounded-2xl bg-white shadow-2xl">
        <div className="flex items-center justify-between border-b border-slate-200 px-6 py-4">
          <h2 className="text-xl font-bold">{title}</h2>
          <button
            onClick={onClose}
            type="button"
            className="rounded-lg p-2 hover:bg-slate-100"
          >
            <X size={20} />
          </button>
        </div>
        <div className="p-6">{children}</div>
      </div>
    </div>
  );
}

function FormInput({
  label,
  type = "text",
  value,
  onChange,
  placeholder,
  required,
}) {
  return (
    <div>
      <label className="mb-2 block text-sm font-medium">
        {label}
        {required && <span className="text-red-500"> *</span>}
      </label>
      <input
        type={type}
        value={value}
        onChange={(e) => onChange(e.target.value)}
        placeholder={placeholder}
        required={required}
        min={type === "number" ? "0.01" : undefined}
        step={type === "number" ? "0.01" : undefined}
        className="w-full rounded-xl border border-slate-200 px-4 py-3 outline-none focus:border-amber-500 focus:ring-2 focus:ring-amber-100"
      />
    </div>
  );
}

function ModalButtons({ onCancel, loading }) {
  return (
    <div className="flex justify-end gap-3 pt-3">
      <button
        type="button"
        onClick={onCancel}
        className="rounded-xl border border-slate-200 px-5 py-2.5 text-sm font-medium"
      >
        Cancel
      </button>
      <button
        type="submit"
        disabled={loading}
        className="rounded-xl bg-amber-500 px-5 py-2.5 text-sm font-semibold text-white hover:bg-amber-600 disabled:opacity-50"
      >
        {loading ? "Saving..." : "Save"}
      </button>
    </div>
  );
}