// GRN.jsx — Firestore version
// ============================================================
// Firestore collections used:
//   - GRN          (goods received notes; each doc embeds items[])
//   - PO           (purchase orders; one doc per product row)
//   - Suppliers    (for supplier autocomplete)
//   - Products     (for manual product search)
//   - Locations    (for location dropdown)
//
// Notes:
//   - PO.js stores one document per PO row (per product). A
//     single PO is therefore spread across several documents
//     that share the same `pono` field. We group by `pono` on
//     recall and derive ReceivedQty by summing matching GRN
//     line items across all related GRNs.
//   - Save is a single createDoc — items live inside the GRN
//     document as an array (no multi-doc transaction needed).
// ============================================================

import React, {
  useContext,
  useEffect,
  useMemo,
  useState,
} from "react";

import { serverTimestamp } from "firebase/firestore";

import {
  COLLECTIONS,
  listCollection,
  createDoc,
} from "../lib/firestore.js";

import { AuthContext } from "../pos/SERVER/AuthContext.js";

/* ======================================================
   COLLECTIONS  (rename here if your Firestore differs)
====================================================== */

const GRNS = "GRN";
const PURCHASE_ORDERS = "PO";
const SUPPLIERS = "Suppliers";
const PRODUCTS = "Products";

/* ======================================================
   FIELD HELPERS
====================================================== */

// Return the first non-null/non-undefined value from the given
// candidate keys, or "" when nothing matches.
const pick = (obj, ...keys) => {
  for (const key of keys) {
    if (obj && obj[key] !== undefined && obj[key] !== null) {
      return obj[key];
    }
  }
  return "";
};

const pad = (n, len = 5) => String(n).padStart(len, "0");

/* ======================================================
   CONSTANTS
====================================================== */

const EMPTY_ITEM = {
  ProductCode: "",
  ProductName: "",
  POQty: 0,
  AlreadyReceivedQty: 0,
  RemainingQty: 0,
  Qty: 0,
  CostPrice: 0,
  FixedDiscountPercentage: 0,
};

const EMPTY_GRN = {
  grnno: "",
  grndate: new Date().toISOString().split("T")[0],
  suppliercode: "",
  suppliername: "",
  referenceno: "",
  pono: "",
  location: "",
  paymenttype: "",
  remark: "",
};

/* ======================================================
   COMPONENT
====================================================== */

function GoodsReceivedNote() {
  const { user } = useContext(AuthContext);

  const username =
    user?.username || user?.U || user?.userName || "";

  const [grn, setGrn] = useState(EMPTY_GRN);
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState("");
  const [errorMessage, setErrorMessage] = useState("");

  const [productQuery, setProductQuery] = useState("");
  const [productResults, setProductResults] = useState([]);
  const [supplierQuery, setSupplierQuery] = useState("");
  const [supplierResults, setSupplierResults] = useState([]);
  const [locations, setLocations] = useState([]);
  const [supplierSelected, setSupplierSelected] = useState(false);

  /* ======================================================
     CACHED LOOKUPS (so we don't re-query on each keystroke)
  ====================================================== */

  const [allSuppliers, setAllSuppliers] = useState([]);
  const [suppliersLoaded, setSuppliersLoaded] = useState(false);

  const [allProducts, setAllProducts] = useState([]);
  const [productsLoaded, setProductsLoaded] = useState(false);

  /* ======================================================
     INITIAL LOAD
  ====================================================== */

  useEffect(() => {
    generateGRNNumber();
    loadLocations();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  /* ======================================================
     GRN NUMBER
  ====================================================== */

  const generateGRNNumber = async () => {
    try {
      const rows = await listCollection(GRNS);

      let maxNumber = 0;

      rows.forEach((row) => {
        const raw = pick(row, "GRNNo", "grnno");
        const match = String(raw).match(/(\d+)$/);

        if (match) {
          const n = Number(match[1]);
          if (Number.isFinite(n) && n > maxNumber) {
            maxNumber = n;
          }
        }
      });

      const newGRN = `GRN${pad(maxNumber + 1, 5)}`;

      setGrn((prev) => ({ ...prev, grnno: newGRN }));
    } catch (error) {
      console.error("GRN NUMBER ERROR:", error);

      setGrn((prev) => ({ ...prev, grnno: "GRN00001" }));

      setErrorMessage(
        "Unable to determine next GRN number. Defaulting to GRN00001."
      );
    }
  };

  /* ======================================================
     LOCATIONS
  ====================================================== */

  const loadLocations = async () => {
    try {
      console.log("Loading locations from Firestore...");

      const rows = await listCollection(COLLECTIONS.LOCATIONS, {
        where: [["IsDelete", "==", 0]],
      });

      console.log("LOCATION ROWS:", rows);

      setLocations(rows);

      if (rows.length === 0) {
        console.warn("No locations returned from Firestore.");
        setErrorMessage("No locations found.");
      }
    } catch (error) {
      console.error("LOCATION LOAD ERROR:", error);
      setErrorMessage(
        error.message || "Unable to load locations."
      );
    }
  };

  /* ======================================================
     HEADER CHANGE
  ====================================================== */

  const handleGrnChange = (e) => {
    const { name, value } = e.target;

    setGrn((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

  /* ======================================================
     SUPPLIER SEARCH
  ====================================================== */

  const searchSuppliers = async (value) => {
    setSupplierQuery(value);
    setSupplierSelected(false);

    const q = String(value || "").trim().toLowerCase();

    if (!q) {
      setSupplierResults([]);
      return;
    }

    try {
      let source = allSuppliers;

      if (!suppliersLoaded) {
        source = await listCollection(SUPPLIERS, {
          where: [["IsDelete", "==", 0]],
        });

        setAllSuppliers(source);
        setSuppliersLoaded(true);
      }

      const filtered = source
        .filter((s) => {
          const code = String(
            pick(
              s,
              "SupplierCode",
              "suppliercode",
              "Code",
              "code"
            )
          ).toLowerCase();

          const name = String(
            pick(
              s,
              "SupplierName",
              "suppliername",
              "Name",
              "name"
            )
          ).toLowerCase();

          return code.includes(q) || name.includes(q);
        })
        .slice(0, 20);

      setSupplierResults(filtered);
    } catch (error) {
      console.error("SUPPLIER SEARCH ERROR:", error);
      setSupplierResults([]);
    }
  };

  /* ======================================================
     SELECT SUPPLIER
  ====================================================== */

  const selectSupplier = (supplier) => {
    const code = pick(
      supplier,
      "SupplierCode",
      "suppliercode",
      "Code",
      "code"
    );

    const name = pick(
      supplier,
      "SupplierName",
      "suppliername",
      "Name",
      "name"
    );

    setGrn((prev) => ({
      ...prev,
      suppliercode: code,
      suppliername: name,
    }));

    setSupplierQuery(`${code} - ${name}`);
    setSupplierResults([]);
    setSupplierSelected(true);
  };

  /* ======================================================
     PRODUCT SEARCH
  ====================================================== */

  const searchProducts = async (value) => {
    setProductQuery(value);

    const q = String(value || "").trim().toLowerCase();

    if (!q) {
      setProductResults([]);
      return;
    }

    try {
      let source = allProducts;

      if (!productsLoaded) {
        source = await listCollection(PRODUCTS, {
          where: [["IsDelete", "==", 0]],
        });

        setAllProducts(source);
        setProductsLoaded(true);
      }

      const filtered = source
        .filter((p) => {
          const code = String(
            pick(p, "ProductCode", "productcode")
          ).toLowerCase();

          const name = String(
            pick(p, "ProductName", "productname")
          ).toLowerCase();

          return code.includes(q) || name.includes(q);
        })
        .slice(0, 20);

      setProductResults(filtered);
    } catch (error) {
      console.error("PRODUCT SEARCH ERROR:", error);
      setProductResults([]);
    }
  };

  /* ======================================================
     ADD PRODUCT (manual, without PO)
  ====================================================== */

  const addProduct = (product) => {
    const code = pick(product, "ProductCode", "productcode");
    const name = pick(product, "ProductName", "productname");

    const price = Number(
      pick(
        product,
        "CostPrice",
        "costprice",
        "SellingPrice",
        "sellingprice",
        "Price",
        "price"
      ) || 0
    );

    if (!code) {
      setErrorMessage("Selected product has no code.");
      return;
    }

    if (items.some((item) => item.ProductCode === code)) {
      setErrorMessage(`${code} is already added.`);
      return;
    }

    setItems((prev) => [
      ...prev,
      {
        ...EMPTY_ITEM,
        ProductCode: code,
        ProductName: name,
        Qty: 1,
        CostPrice: price,
        RemainingQty: 0,
      },
    ]);

    setProductQuery("");
    setProductResults([]);
    setErrorMessage("");
  };

  /* ======================================================
     REMOVE / UPDATE ITEM
  ====================================================== */

  const removeItem = (index) => {
    setItems((prev) => prev.filter((_, i) => i !== index));
  };

  const updateItem = (index, field, value) => {
    setItems((prev) =>
      prev.map((item, i) => {
        if (i !== index) return item;

        let newValue = value;

        if (
          field === "Qty" ||
          field === "CostPrice" ||
          field === "FixedDiscountPercentage"
        ) {
          newValue = value === "" ? "" : Number(value);
        }

        return { ...item, [field]: newValue };
      })
    );
  };

  /* ======================================================
     RECALL PO
     ------------------------------------------------------
     Firestore does not have a "get me this PO with
     received qty already computed" endpoint, so we:

       1. Load all PO rows where pono == <poNumber>
       2. Load all GRN docs where PONo == <poNumber>
       3. Aggregate GRN items → received qty per product
       4. Subtract from each PO row's qty to get remaining
  ====================================================== */

  const recallPO = async () => {
    const poNumber = String(grn.pono || "").trim();

    if (!poNumber) {
      setErrorMessage("Please enter PO Number.");
      return;
    }

    try {
      setLoading(true);
      setMessage("");
      setErrorMessage("");

      /* ---- 1. PO rows ---- */

      const poRows = await listCollection(PURCHASE_ORDERS, {
        where: [["pono", "==", poNumber]],
      });

      if (!poRows || poRows.length === 0) {
        setErrorMessage(
          `PO ${poNumber} not found.`
        );
        return;
      }

      const header = poRows[0];

      /* ---- 2. Related GRNs ---- */

      const relatedGRNs = await listCollection(GRNS, {
        where: [["PONo", "==", poNumber]],
      });

      /* ---- 3. Received qty per product ---- */

      const receivedByProduct = {};

      relatedGRNs.forEach((g) => {
        (g.items || []).forEach((it) => {
          const code = it.ProductCode;
          if (!code) return;

          receivedByProduct[code] =
            (receivedByProduct[code] || 0) +
            Number(it.Qty || 0);
        });
      });

      /* ---- 4. Header ---- */

      setGrn((prev) => ({
        ...prev,
        pono:
          pick(header, "pono", "PONo", "poNo") || poNumber,
        suppliercode:
          pick(header, "suppliercode", "SupplierCode") || "",
        suppliername:
          pick(header, "suppliername", "SupplierName") || "",
        location: String(
          pick(
            header,
            "location",
            "Location",
            "LocationID"
          ) || ""
        ),
        paymenttype:
          pick(
            header,
            "paymenttern",
            "paymenttype",
            "PaymentType",
            "paymentTerm"
          ) || "",
        referenceno:
          pick(header, "referenceno", "ReferenceNo") || "",
        remark: pick(header, "Remark", "remark") || "",
      }));

      /* ---- 5. Items ---- */

      const recalledItems = poRows.map((row) => {
        const code = pick(row, "productcode", "ProductCode");
        const poQty = Number(pick(row, "qty", "POQty") || 0);
        const already = receivedByProduct[code] || 0;
        const remaining = Math.max(poQty - already, 0);

        return {
          ...EMPTY_ITEM,
          ProductCode: code,
          ProductName:
            pick(row, "productname", "ProductName") || "",
          POQty: poQty,
          AlreadyReceivedQty: already,
          RemainingQty: remaining,
          Qty: 0,
          CostPrice: Number(
            pick(
              row,
              "costprice",
              "sellingprice",
              "CostPrice",
              "SellingPrice"
            ) || 0
          ),
          FixedDiscountPercentage: Number(
            pick(
              row,
              "fixeddiscountpercentage",
              "FixedDiscountPercentage"
            ) || 0
          ),
        };
      });

      setItems(recalledItems);
      setProductQuery("");
      setProductResults([]);

      setSupplierQuery(
        `${pick(header, "suppliercode", "SupplierCode")} - ${pick(
          header,
          "suppliername",
          "SupplierName"
        )}`
      );
      setSupplierSelected(true);

      setMessage(
        `PO ${poNumber} recalled successfully. ${recalledItems.length} product(s) loaded.`
      );
    } catch (error) {
      console.error("PO RECALL ERROR:", error);
      setErrorMessage(
        error.message || "Unable to recall PO."
      );
    } finally {
      setLoading(false);
    }
  };

  /* ======================================================
     TOTALS
  ====================================================== */

  const totals = useMemo(() => {
    let qty = 0;
    let gross = 0;
    let discount = 0;
    let net = 0;

    items.forEach((item) => {
      const itemQty = Number(item.Qty || 0);
      const price = Number(item.CostPrice || 0);
      const disc = Number(item.FixedDiscountPercentage || 0);

      const itemGross = itemQty * price;
      const itemDiscount = (itemGross * disc) / 100;
      const itemNet = itemGross - itemDiscount;

      qty += itemQty;
      gross += itemGross;
      discount += itemDiscount;
      net += itemNet;
    });

    return { qty, gross, discount, net };
  }, [items]);

  /* ======================================================
     VALIDATE
  ====================================================== */

  const validateForm = () => {
    if (!grn.grnno.trim()) {
      setErrorMessage("GRN Number is required.");
      return false;
    }

    if (!grn.grndate) {
      setErrorMessage("GRN Date is required.");
      return false;
    }

    if (!grn.suppliercode.trim()) {
      setErrorMessage("Supplier Code is required.");
      return false;
    }

    if (!grn.location) {
      setErrorMessage("Location is required.");
      return false;
    }

    if (items.length === 0) {
      setErrorMessage("Please add at least one product.");
      return false;
    }

    for (let i = 0; i < items.length; i += 1) {
      const item = items[i];

      if (!item.ProductCode) {
        setErrorMessage(
          `Product code is required at row ${i + 1}.`
        );
        return false;
      }

      const qty = Number(item.Qty || 0);

      if (qty <= 0) {
        setErrorMessage(
          `Invalid quantity for ${item.ProductCode}.`
        );
        return false;
      }

      if (
        Number(item.RemainingQty || 0) > 0 &&
        qty > Number(item.RemainingQty)
      ) {
        setErrorMessage(
          `${item.ProductCode}: received quantity ${qty} cannot exceed remaining PO quantity ${item.RemainingQty}.`
        );
        return false;
      }
    }

    return true;
  };

  /* ======================================================
     SAVE GRN
  ====================================================== */

  const handleSave = async (e) => {
    e.preventDefault();

    setMessage("");
    setErrorMessage("");

    if (!validateForm()) return;

    try {
      setLoading(true);

      const data = {
        GRNNo: grn.grnno.trim(),
        GRNDate: grn.grndate,
        SupplierCode: grn.suppliercode.trim(),
        SupplierName: grn.suppliername.trim(),
        ReferenceNo: grn.referenceno?.trim() || "",
        PONo: grn.pono?.trim() || "",
        LocationID: grn.location,
        PaymentType: grn.paymenttype || "",
        Remark: grn.remark?.trim() || "",
        TotalQty: totals.qty,
        TotalGross: totals.gross,
        TotalDiscount: totals.discount,
        TotalNet: totals.net,
        items: items.map((item) => ({
          ProductCode: item.ProductCode,
          ProductName: item.ProductName,
          Qty: Number(item.Qty || 0),
          CostPrice: Number(item.CostPrice || 0),
          FixedDiscountPercentage: Number(
            item.FixedDiscountPercentage || 0
          ),
        })),
        CreatedAt: serverTimestamp(),
        CreatedBy: username,
        IsDelete: 0,
      };

      console.log("GRN SAVE PAYLOAD:", data);

      await createDoc(GRNS, data, { username });

      setMessage(
        `GRN ${grn.grnno} saved successfully.`
      );

      // Reset form
      setGrn(EMPTY_GRN);
      setItems([]);
      setSupplierQuery("");
      setSupplierResults([]);
      setProductQuery("");
      setProductResults([]);
      setSupplierSelected(false);

      await generateGRNNumber();
    } catch (error) {
      console.error("GRN SAVE ERROR:", error);
      setErrorMessage(
        error.message || "Error saving GRN."
      );
    } finally {
      setLoading(false);
    }
  };

  /* ======================================================
     CANCEL
  ====================================================== */

  const handleCancel = () => {
    setGrn(EMPTY_GRN);
    setItems([]);
    setSupplierQuery("");
    setSupplierResults([]);
    setProductQuery("");
    setProductResults([]);
    setSupplierSelected(false);
    setMessage("");
    setErrorMessage("");
    generateGRNNumber();
  };

  /* ======================================================
     RENDER
  ====================================================== */

  return (
    <div className="min-h-screen bg-gray-100 p-4 md:p-6">
      <div className="mx-auto max-w-7xl">
        {/* HEADER */}

        <div className="mb-5">
          <h1 className="text-2xl font-bold text-gray-800">
            Goods Received Note
          </h1>
          <p className="text-sm text-gray-500">
            Receive products against Purchase Orders
          </p>
        </div>

        {/* MESSAGES */}

        {message && (
          <div className="mb-4 rounded-lg border border-green-200 bg-green-50 px-4 py-3 text-sm text-green-700">
            {message}
          </div>
        )}

        {errorMessage && (
          <div className="mb-4 rounded-lg border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">
            {errorMessage}
          </div>
        )}

        <form onSubmit={handleSave}>
          {/* GRN HEADER */}

          <div className="mb-5 rounded-xl bg-white p-5 shadow-sm">
            <h2 className="mb-4 text-lg font-semibold text-gray-800">
              GRN Information
            </h2>

            <div className="grid grid-cols-1 gap-4 md:grid-cols-2 lg:grid-cols-4">
              {/* GRN NUMBER */}

              <div>
                <label className="mb-1 block text-sm font-semibold text-gray-700">
                  GRN Number
                </label>
                <input
                  type="text"
                  value={grn.grnno}
                  readOnly
                  className="w-full rounded-lg border border-gray-300 bg-gray-100 px-3 py-2 text-sm"
                />
              </div>

              {/* DATE */}

              <div>
                <label className="mb-1 block text-sm font-semibold text-gray-700">
                  GRN Date
                </label>
                <input
                  type="date"
                  name="grndate"
                  value={grn.grndate}
                  onChange={handleGrnChange}
                  className="w-full rounded-lg border border-gray-300 px-3 py-2 text-sm"
                />
              </div>

              {/* PO NUMBER */}

              <div className="md:col-span-2">
                <label className="mb-1 block text-sm font-semibold text-gray-700">
                  PO Number
                </label>
                <div className="flex gap-2">
                  <input
                    type="text"
                    name="pono"
                    value={grn.pono}
                    onChange={handleGrnChange}
                    placeholder="Enter PO Number"
                    className="min-w-0 flex-1 rounded-lg border border-gray-300 px-3 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-200"
                  />
                  <button
                    type="button"
                    onClick={recallPO}
                    disabled={loading || !grn.pono.trim()}
                    className="rounded-lg bg-blue-600 px-5 py-2 text-sm font-semibold text-white hover:bg-blue-700 disabled:cursor-not-allowed disabled:opacity-50"
                  >
                    {loading ? "Loading..." : "Recall PO"}
                  </button>
                </div>
              </div>

              {/* SUPPLIER */}

              <div className="relative">
                <label className="mb-1 block text-sm font-semibold text-gray-700">
                  Supplier
                </label>
                <input
                  type="text"
                  value={
                    supplierSelected
                      ? `${grn.suppliercode} - ${grn.suppliername}`
                      : supplierQuery
                  }
                  onChange={(e) =>
                    searchSuppliers(e.target.value)
                  }
                  placeholder="Search supplier"
                  className="w-full rounded-lg border border-gray-300 px-3 py-2 text-sm"
                />

                {supplierResults.length > 0 && (
                  <div className="absolute z-30 mt-1 max-h-52 w-full overflow-auto rounded-lg border bg-white shadow-lg">
                    {supplierResults.map((supplier, index) => {
                      const code = pick(
                        supplier,
                        "SupplierCode",
                        "suppliercode",
                        "Code"
                      );
                      const name = pick(
                        supplier,
                        "SupplierName",
                        "suppliername",
                        "Name"
                      );

                      return (
                        <button
                          type="button"
                          key={index}
                          onClick={() => selectSupplier(supplier)}
                          className="block w-full border-b px-3 py-2 text-left text-sm hover:bg-gray-100"
                        >
                          <span className="font-semibold">
                            {code}
                          </span>
                          {" - "}
                          {name}
                        </button>
                      );
                    })}
                  </div>
                )}
              </div>

              {/* SUPPLIER CODE */}

              <div>
                <label className="mb-1 block text-sm font-semibold text-gray-700">
                  Supplier Code
                </label>
                <input
                  type="text"
                  value={grn.suppliercode}
                  readOnly
                  className="w-full rounded-lg border border-gray-300 bg-gray-100 px-3 py-2 text-sm"
                />
              </div>

              {/* SUPPLIER NAME */}

              <div>
                <label className="mb-1 block text-sm font-semibold text-gray-700">
                  Supplier Name
                </label>
                <input
                  type="text"
                  value={grn.suppliername}
                  readOnly
                  className="w-full rounded-lg border border-gray-300 bg-gray-100 px-3 py-2 text-sm"
                />
              </div>

              {/* LOCATION */}

              <div>
                <label className="mb-1 block text-sm font-semibold text-gray-700">
                  Location
                </label>
                <select
                  name="location"
                  value={grn.location}
                  onChange={handleGrnChange}
                  className="w-full rounded-lg border border-gray-300 bg-white px-3 py-2 text-sm"
                >
                  <option value="">Select Location</option>

                  {locations.map((loc, index) => {
                    const id =
                      loc.LocationID ??
                      loc.locationID ??
                      loc.id ??
                      loc.ID ??
                      "";

                    const name =
                      loc.LocationName ??
                      loc.locationname ??
                      loc.Location ??
                      loc.location ??
                      "";

                    return (
                      <option key={index} value={id}>
                        {name}
                      </option>
                    );
                  })}
                </select>
              </div>

              {/* PAYMENT */}

              <div>
                <label className="mb-1 block text-sm font-semibold text-gray-700">
                  Payment Type
                </label>
                <select
                  name="paymenttype"
                  value={grn.paymenttype}
                  onChange={handleGrnChange}
                  className="w-full rounded-lg border border-gray-300 bg-white px-3 py-2 text-sm"
                >
                  <option value="">Select Payment</option>
                  <option value="Cash">Cash</option>
                  <option value="Credit">Credit</option>
                  <option value="Cheque">Cheque</option>
                  <option value="Bank">Bank</option>
                </select>
              </div>

              {/* REFERENCE */}

              <div>
                <label className="mb-1 block text-sm font-semibold text-gray-700">
                  Reference No
                </label>
                <input
                  type="text"
                  name="referenceno"
                  value={grn.referenceno}
                  onChange={handleGrnChange}
                  className="w-full rounded-lg border border-gray-300 px-3 py-2 text-sm"
                />
              </div>

              {/* REMARK */}

              <div className="md:col-span-2 lg:col-span-4">
                <label className="mb-1 block text-sm font-semibold text-gray-700">
                  Remark
                </label>
                <textarea
                  name="remark"
                  value={grn.remark}
                  onChange={handleGrnChange}
                  rows={2}
                  className="w-full rounded-lg border border-gray-300 px-3 py-2 text-sm"
                />
              </div>
            </div>
          </div>

          {/* PRODUCT SEARCH */}

          <div className="mb-5 rounded-xl bg-white p-5 shadow-sm">
            <div className="mb-4 flex flex-col gap-3 md:flex-row md:items-center md:justify-between">
              <div>
                <h2 className="text-lg font-semibold text-gray-800">
                  Add Product
                </h2>
                <p className="text-xs text-gray-500">
                  Search and add products manually
                </p>
              </div>

              <div className="relative w-full md:w-96">
                <input
                  type="text"
                  value={productQuery}
                  onChange={(e) =>
                    searchProducts(e.target.value)
                  }
                  placeholder="Search product code or name..."
                  className="w-full rounded-lg border border-gray-300 px-3 py-2 text-sm"
                />

                {productResults.length > 0 && (
                  <div className="absolute z-20 mt-1 max-h-60 w-full overflow-auto rounded-lg border bg-white shadow-lg">
                    {productResults.map((product, index) => {
                      const code = pick(
                        product,
                        "ProductCode",
                        "productcode"
                      );
                      const name = pick(
                        product,
                        "ProductName",
                        "productname"
                      );

                      return (
                        <button
                          type="button"
                          key={index}
                          onClick={() => addProduct(product)}
                          className="block w-full border-b px-3 py-2 text-left hover:bg-gray-100"
                        >
                          <div className="font-semibold text-gray-800">
                            {code}
                          </div>
                          <div className="text-xs text-gray-500">
                            {name}
                          </div>
                        </button>
                      );
                    })}
                  </div>
                )}
              </div>
            </div>
          </div>

          {/* ITEMS */}

          <div className="mb-5 overflow-hidden rounded-xl bg-white shadow-sm">
            <div className="border-b px-5 py-4">
              <h2 className="text-lg font-semibold text-gray-800">
                Received Items
              </h2>
            </div>

            <div className="overflow-x-auto">
              <table className="w-full min-w-[1100px] text-sm">
                <thead className="bg-gray-100">
                  <tr>
                    <th className="px-3 py-3 text-left">#</th>
                    <th className="px-3 py-3 text-left">
                      Product Code
                    </th>
                    <th className="px-3 py-3 text-left">
                      Product Name
                    </th>
                    <th className="px-3 py-3 text-right">
                      PO Qty
                    </th>
                    <th className="px-3 py-3 text-right">
                      Already Received
                    </th>
                    <th className="px-3 py-3 text-right">
                      Remaining
                    </th>
                    <th className="px-3 py-3 text-right">
                      GRN Qty
                    </th>
                    <th className="px-3 py-3 text-right">
                      Cost Price
                    </th>
                    <th className="px-3 py-3 text-right">
                      Discount %
                    </th>
                    <th className="px-3 py-3 text-right">
                      Amount
                    </th>
                    <th className="px-3 py-3 text-center">
                      Action
                    </th>
                  </tr>
                </thead>

                <tbody>
                  {items.length === 0 ? (
                    <tr>
                      <td
                        colSpan="11"
                        className="px-4 py-10 text-center text-gray-400"
                      >
                        No products added. Recall a PO or
                        search for a product.
                      </td>
                    </tr>
                  ) : (
                    items.map((item, index) => {
                      const qty = Number(item.Qty || 0);
                      const price = Number(
                        item.CostPrice || 0
                      );
                      const discount = Number(
                        item.FixedDiscountPercentage || 0
                      );

                      const gross = qty * price;
                      const discountAmount =
                        (gross * discount) / 100;
                      const amount =
                        gross - discountAmount;

                      return (
                        <tr
                          key={`${item.ProductCode}-${index}`}
                          className="border-t hover:bg-gray-50"
                        >
                          <td className="px-3 py-2">
                            {index + 1}
                          </td>

                          <td className="px-3 py-2 font-semibold">
                            {item.ProductCode}
                          </td>

                          <td className="px-3 py-2">
                            {item.ProductName}
                          </td>

                          <td className="px-3 py-2 text-right">
                            {item.POQty || "-"}
                          </td>

                          <td className="px-3 py-2 text-right">
                            {item.AlreadyReceivedQty || 0}
                          </td>

                          <td className="px-3 py-2 text-right font-semibold">
                            {item.RemainingQty || "-"}
                          </td>

                          <td className="px-3 py-2">
                            <input
                              type="number"
                              min="0"
                              max={
                                item.RemainingQty > 0
                                  ? item.RemainingQty
                                  : undefined
                              }
                              value={item.Qty}
                              onChange={(e) =>
                                updateItem(
                                  index,
                                  "Qty",
                                  e.target.value
                                )
                              }
                              className="w-24 rounded border px-2 py-1 text-right"
                            />
                          </td>

                          <td className="px-3 py-2">
                            <input
                              type="number"
                              min="0"
                              step="0.01"
                              value={item.CostPrice}
                              onChange={(e) =>
                                updateItem(
                                  index,
                                  "CostPrice",
                                  e.target.value
                                )
                              }
                              className="w-28 rounded border px-2 py-1 text-right"
                            />
                          </td>

                          <td className="px-3 py-2">
                            <input
                              type="number"
                              min="0"
                              max="100"
                              step="0.01"
                              value={
                                item.FixedDiscountPercentage
                              }
                              onChange={(e) =>
                                updateItem(
                                  index,
                                  "FixedDiscountPercentage",
                                  e.target.value
                                )
                              }
                              className="w-24 rounded border px-2 py-1 text-right"
                            />
                          </td>

                          <td className="px-3 py-2 text-right font-semibold">
                            {amount.toFixed(2)}
                          </td>

                          <td className="px-3 py-2 text-center">
                            <button
                              type="button"
                              onClick={() =>
                                removeItem(index)
                              }
                              className="rounded bg-red-100 px-3 py-1 text-xs font-semibold text-red-600 hover:bg-red-200"
                            >
                              Remove
                            </button>
                          </td>
                        </tr>
                      );
                    })
                  )}
                </tbody>
              </table>
            </div>
          </div>

          {/* TOTALS */}

          <div className="mb-5 flex justify-end">
            <div className="w-full rounded-xl bg-white p-5 shadow-sm md:w-96">
              <div className="flex justify-between py-2">
                <span className="text-gray-500">
                  Total Qty
                </span>
                <span className="font-semibold">
                  {totals.qty}
                </span>
              </div>

              <div className="flex justify-between py-2">
                <span className="text-gray-500">
                  Gross Amount
                </span>
                <span className="font-semibold">
                  {totals.gross.toFixed(2)}
                </span>
              </div>

              <div className="flex justify-between py-2">
                <span className="text-gray-500">
                  Discount
                </span>
                <span className="font-semibold">
                  {totals.discount.toFixed(2)}
                </span>
              </div>

              <div className="mt-2 flex justify-between border-t pt-3">
                <span className="text-lg font-bold">
                  Net Total
                </span>
                <span className="text-lg font-bold text-blue-600">
                  {totals.net.toFixed(2)}
                </span>
              </div>
            </div>
          </div>

          {/* BUTTONS */}

          <div className="flex flex-col justify-end gap-3 sm:flex-row">
            <button
              type="button"
              onClick={handleCancel}
              disabled={loading}
              className="rounded-lg border border-gray-300 bg-white px-6 py-2.5 font-semibold text-gray-700 hover:bg-gray-50 disabled:opacity-50"
            >
              Clear
            </button>

            <button
              type="submit"
              disabled={loading || items.length === 0}
              className="rounded-lg bg-green-600 px-8 py-2.5 font-semibold text-white hover:bg-green-700 disabled:cursor-not-allowed disabled:opacity-50"
            >
              {loading ? "Saving..." : "Save GRN"}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

export default GoodsReceivedNote;