// registration.jsx — Firestore version
// ============================================================
// Firestore collections used:
//   - Users  (one document per registered user)
//
// Behaviour change vs. the SQL version:
//   - The original hashed the password with bcrypt but then
//     sent the plaintext password to the backend. That bug is
//     fixed here: only PasswordHash is stored.
//   - Duplicate usernames are checked before createDoc.
// ============================================================

import React, { useContext, useState } from "react";
import bcrypt from "bcryptjs";
import { serverTimestamp } from "firebase/firestore";

import { listCollection, createDoc } from "../lib/firestore.js";
import { AuthContext } from "../pos/SERVER/AuthContext.js";

/* ======================================================
   COLLECTIONS
====================================================== */

const USERS = "Users";

/* ======================================================
   COMPONENT
====================================================== */

export default function Register() {
  const { user } = useContext(AuthContext);

  // Who is creating this account?
  // - If an admin is logged in, record them as the creator.
  // - If nobody is logged in (self-registration), record
  //   "self-registration".
  const registeredBy = user?.username || "self-registration";

  const [form, setForm] = useState({
    username: "",
    password: "",
    confirmPassword: "",
  });

  const [message, setMessage] = useState("");
  const [errorMessage, setErrorMessage] = useState("");
  const [loading, setLoading] = useState(false);

  /* ======================================================
     CHANGE
  ====================================================== */

  const handleChange = (e) => {
    setForm({
      ...form,
      [e.target.name]: e.target.value,
    });
  };

  /* ======================================================
     REGISTER
     ------------------------------------------------------
     1. Validate input
     2. Check for duplicate username
     3. Hash password with bcrypt
     4. Save the user document
  ====================================================== */

  const register = async (e) => {
    e.preventDefault();

    setMessage("");
    setErrorMessage("");

    /* ---- 1. Basic validation ---- */

    if (!form.username.trim() || !form.password) {
      setErrorMessage("All fields are required.");
      return;
    }

    if (form.password !== form.confirmPassword) {
      setErrorMessage("Passwords do not match.");
      return;
    }

    if (form.password.length < 6) {
      setErrorMessage(
        "Password must be at least 6 characters."
      );
      return;
    }

    setLoading(true);

    try {
      const username = form.username.trim();

      /* ---- 2. Duplicate check ---- */

      const existing = await listCollection(USERS, {
        where: [["Username", "==", username]],
      });

      if (existing.length > 0) {
        setErrorMessage(
          "Username is already taken. Please choose another."
        );
        return;
      }

      /* ---- 3. Hash password ---- */

      const salt = await bcrypt.genSalt(10);
      const passwordHash = await bcrypt.hash(
        form.password,
        salt
      );

      /* ---- 4. Save ---- */

      await createDoc(
        USERS,
        {
          Username: username,
          PasswordHash: passwordHash,
          IsDelete: 0,
          CreatedAt: serverTimestamp(),
          CreatedBy: registeredBy,
        },
        { username: registeredBy }
      );

      setMessage(
        `User "${username}" registered successfully.`
      );

      setForm({
        username: "",
        password: "",
        confirmPassword: "",
      });
    } catch (error) {
      console.error("REGISTRATION ERROR:", error);
      setErrorMessage(
        error.message || "Registration failed. Please try again."
      );
    } finally {
      setLoading(false);
    }
  };

  /* ======================================================
     RENDER
  ====================================================== */

  return (
    <div className="min-h-screen bg-gray-100 flex justify-center items-center">
      <div className="bg-white w-96 rounded-xl shadow-lg p-8">
        <h1 className="text-3xl font-bold text-center mb-6">
          Register
        </h1>

        <form onSubmit={register}>
          <input
            type="text"
            name="username"
            placeholder="Username"
            value={form.username}
            onChange={handleChange}
            autoComplete="username"
            disabled={loading}
            className="border w-full p-3 rounded-lg mb-4 disabled:bg-gray-100"
          />

          <input
            type="password"
            name="password"
            placeholder="Password"
            value={form.password}
            onChange={handleChange}
            autoComplete="new-password"
            disabled={loading}
            className="border w-full p-3 rounded-lg mb-4 disabled:bg-gray-100"
          />

          <input
            type="password"
            name="confirmPassword"
            placeholder="Confirm Password"
            value={form.confirmPassword}
            onChange={handleChange}
            autoComplete="new-password"
            disabled={loading}
            className="border w-full p-3 rounded-lg mb-6 disabled:bg-gray-100"
          />

          <button
            type="submit"
            disabled={loading}
            className="bg-blue-600 text-white w-full p-3 rounded-lg hover:bg-blue-700 disabled:opacity-60 disabled:cursor-not-allowed"
          >
            {loading ? "Registering..." : "Register"}
          </button>
        </form>

        {message && (
          <p className="text-center mt-4 text-green-600">
            {message}
          </p>
        )}

        {errorMessage && (
          <p className="text-center mt-4 text-red-600">
            {errorMessage}
          </p>
        )}
      </div>
    </div>
  );
}