// src/hooks/usePermissions.jsx
// ============================================================
// Read-side hook for permissions. Thin passthrough to
// PermissionsContext — all logic (fast + slow CashierID
// resolution, cache, network, can / canField evaluation) lives
// in the provider so the hook and context.can() can never
// disagree.
// ============================================================
import { useContext, useCallback } from "react";
import { PermissionsContext } from "../context/PermissionsContext";

export function usePermissions() {
  const ctx = useContext(PermissionsContext);
  if (!ctx) {
    throw new Error("usePermissions must be inside <PermissionsProvider>");
  }

  // Signature is kept 2-arg for backwards compatibility — callers
  // that historically passed a third argument had it ignored, and we
  // continue to ignore it. Use `can(module, permissionName, action)`
  // directly on the context if you need the 3-arg form.
  const can = useCallback(
    (moduleName, action) => ctx.can(moduleName, action),
    [ctx.can]
  );

  const canAny = useCallback(
    (moduleName, action = "CanView") => ctx.canAny(moduleName, action),
    [ctx.canAny]
  );

  const canField = useCallback(
    (moduleName, field) => ctx.canViewField(moduleName, field),
    [ctx.canViewField]
  );

  const reload = useCallback(() => {
    if (typeof ctx.reload === "function") ctx.reload();
  }, [ctx.reload]);

  return {
    permissions: ctx.permissions,
    loading: Boolean(ctx.loading),
    error: ctx.error || "",
    isOffline: Boolean(ctx.isOffline),
    isStale: Boolean(ctx.isStale),
    cachedAt: ctx.cachedAt || null,
    cashierID: ctx.cashierID,
    reload,
    can,
    canAny,
    canField,
  };
}