// src/pos/Logout.js
// ============================================================
// Logout — React + Firebase Auth
// ------------------------------------------------------------
// Preserves:
//   • Layout, card, "Welcome, {user}" text
//   • "Confirm logout" copy
//   • POS_SESSION_ID / POS_COMPUTER_NAME cleanup
//   • Navigate to "/POS/" on confirm
//
// Fixes:
//   • "No" button now navigates back to /home (was a no-op)
//   • Calls Firebase signOut() so the session really ends
//   • Shows a loading state while signing out
// ============================================================
import React, { useContext, useState } from "react";
import { useNavigate } from "react-router-dom";

import { AuthContext } from "./SERVER/AuthContext.js";

export default function Logout() {
  const { user, logout } = useContext(AuthContext);
  const navigate = useNavigate();

  const [signingOut, setSigningOut] = useState(false);
  const [error, setError]           = useState("");

  // ------------------------------------------------------------
  // YES — sign out and clear POS session state
  // ------------------------------------------------------------
  const handleConfirm = async () => {
    setSigningOut(true);
    setError("");

    try {
      // 1. End the Firebase Auth session
      if (typeof logout === "function") {
        await logout();
      }

      // 2. Clear POS-specific local state so the next login
      //    starts fresh from the Open Float screen.
      try {
        localStorage.removeItem("POS_SESSION_ID");
        localStorage.removeItem("POS_COMPUTER_NAME");
        // Legacy keys from the SQL era — harmless if absent
        localStorage.removeItem("token");
        localStorage.removeItem("user");
      } catch (err) {
        console.warn("[Logout] localStorage cleanup:", err);
      }

      // 3. Go back to the login screen
      navigate("/POS/", { replace: true });
    } catch (err) {
      console.error("[Logout] signOut error:", err);
      setError(
        err?.message || "Unable to sign out. Please try again."
      );
      setSigningOut(false);
    }
  };

  // ------------------------------------------------------------
  // NO — stay on the app
  // ------------------------------------------------------------
  const handleCancel = () => {
    navigate("/home", { replace: true });
  };

  return (
    <div className="min-h-screen bg-gray-100 flex items-center justify-center p-4">
      <div className="w-full max-w-2xl bg-white p-6 rounded-xl shadow-2xl border border-gray-200">
        {user?.username ? `Welcome, ${user.username}` : "No user logged in"}

        <h2 className="text-2xl font-bold mb-4 text-center">Logout</h2>

        <p className="text-center text-gray-600 mb-6">
          Confirm logout to end your current session. For your security,
          you will need to sign in again to access your account.
        </p>

        {error && (
          <div className="mb-4 rounded-lg border border-red-200 bg-red-50 px-4 py-3 text-sm font-medium text-red-700">
            ⚠ {error}
          </div>
        )}

        <div className="grid grid-cols-2 gap-4">
          <button
            type="button"
            onClick={handleConfirm}
            disabled={signingOut}
            className="bg-indigo-600 text-white py-2 rounded hover:bg-indigo-500 disabled:bg-indigo-300 disabled:cursor-not-allowed"
          >
            {signingOut ? "Signing out…" : "Yes"}
          </button>

          <button
            type="button"
            onClick={handleCancel}
            disabled={signingOut}
            className="bg-gray-200 text-gray-800 py-2 rounded hover:bg-gray-300 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            No
          </button>
        </div>
      </div>
    </div>
  );
}